quests[73025] = { id = 73025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nistklufttour", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[73026] = { id = 73026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beutebucht", description = "Land der Piraten, Schwindler und Räuber! Zeros, einst ein gefangener Welpling, hat sich einen ausgezeichneten Ruf als Auktionshaushändler in einem der skrupellosesten Orte in ganz Azeroth erarbeitet.\n\nMit seiner letzten Fehlinvestition hat er es aber tatsächlich auf die Titelseite des Beutebucht-Anzeigers geschafft. Rettet ihn, bevor ihn der Baron selbst aufsucht und seine Schulden eintreibt.", sourceObjective = "Sprecht mit Senegos, um mehr zu erfahren.", completion = "Glaubt Ihr, ich weiß irgendwas über Beutebucht? In der Tat, das tue ich...", sourceObjectiveStatus = "unverified-source-field" }
quests[73027] = { id = 73027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nistklufttour - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
