quests[73030] = { id = 73030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Südinselroute - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[73031] = { id = 73031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Winterpelze", description = "Ich danke Euch für alles, was Ihr getan habt, {name}.\n\nEs ist viel zu einfach, sich zurückzuziehen und einfach in dieser Haltung zu verweilen.\n\nDie Winterpelze werden in die Welt zurückkehren. Wir werden auf den Pfad zurückkehren, von dem unsere Ahnen abgewichen sind.\n\nUnd wir werden Euren Anteil daran nie vergessen.\n\nIch habe den Stamm und unsere neuen Verbündeten versammelt, um zu feiern. Sprecht mit mir, wenn Ihr bereit seid, anzufangen.", sourceObjective = "Sprecht mit Kranac, um die Zeremonie zu beginnen.", completion = "Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[73032] = { id = 73032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Südinselroute - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[73033] = { id = 73033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalderakurven", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[73034] = { id = 73034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalderakurven - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[73035] = { id = 73035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Vertrauens", description = "Radza schickt mich, um Euch zu sagen, dass Ihr zu ihr kommen sollt. Sie hat ihr Räuchergefäß aufgestellt, was bedeutet, dass sie ein Ritual durchführen wird.\n\nDas heißt, was immer sie möchte, ist wichtig.\n\nRadza befindet sich westlich von hier. Ich würde sie nicht warten lassen!", sourceObjective = "Sprecht mit Radza Donnerklaue in der Winterpelzhöhle.", completion = "Danke, dass Ihr gekommen seid. Die Winterpelzschamanen haben begonnen, uns zu vertrauen! Es liegt eine Menge Arbeit vor uns...", sourceObjectiveStatus = "unverified-source-field" }
quests[73036] = { id = 73036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medizinische Pilze", description = "Als wir auf diese armen Seelen stießen, war es klar, dass sie von Djaradin angegriffen wurden. Das den Waffen dieser Bestien anhaftende Gift hindert mich und ihre Anführerin Narvra daran, sie zu heilen.\n\nIch habe auf einigen Kristallen in der Nähe sonderbare Pilze entdeckt. Ich habe diese Pilze schon einmal gesehen und vielleicht kann ich daraus ein Gegenmittel herstellen.\n\nKönntet Ihr ein paar davon besorgen, während Voraxian und ich hier Wache halten?", sourceObjective = "Sammelt 10 Hängepilzzuschnitte am Viridianthron.", progress = "Habt Ihr die Zuschnitte? Ich weiß nicht, wie viel Zeit diesen armen Leuten noch bleibt.", completion = "Danke. Sieht aus, als wären die ganz brauchbar.\n\nIch werde eine Weile brauchen, alle Sterblichen zu heilen, aber wir sollten es hinbekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73037] = { id = 73037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilkristalle", description = "Seid gegrüßt!\n\nEntschuldigt, falls ich... abgelenkt wirke. Ich mache mir solche Sorgen um meine verletzten Freunde, dass ich völlig neben mir stehe.\n\nAber vielleicht habt Ihr ja ein großes Herz und könnt uns helfen.\n\nNarvra braucht Hilfe bei unserer Heilung. Kristallelementarsplitter besitzen heilende Eigenschaften. Ich fordere nur ungern dazu auf, einen Elementar anzugreifen, aber wenn Ihr vielleicht einige davon... auftreiben könntet, würde das meinen Freunden wirklich helfen.\n\nKeine Sorge, die Elementare regenerieren sich mit der Zeit. Die Nöte meiner Freunde gehen vor, ganz egal, wie unhöflich unsere Methoden beim Sammeln auch sein mögen.", sourceObjective = "Sammelt 10 Viridianherzkristalle von Gegnern am Viridianthron.", progress = "Habt Ihr die Kristalle gefunden? Ich mache mir Sorgen um Butterfinger. Ihm geht es richtig schlecht.", completion = "<Narvra zuckt zusammen.>\n\nHabt Dank. Diese Kristalle sollten uns helfen, alle wieder zu heilen.\n\nMich eingeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73038] = { id = 73038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zimmer ohne Aussicht", description = "Dieses Gewölbe wurde von schwarzen Drachen geschaffen, was bedeutet, dass ihre Inhalte Eigentum meines Schwarms sind.\n\nNormalerweise hätte ich vorgeschlagen, dass wir uns dort gemeinsam hineinwagen, aber ich habe nicht mit diesen aggressiven Hütern gerechnet. Ich werde Rupert beschützen, während Ihr nach Artefakten sucht, die wir untersuchen können.\n\nUm Euch zu schützen, werde ich Euch mit einem Zauber belegen, den ich im Kampf gegen die Gronn benutze.", sourceObjective = "Bergt Artefakte aus dem Begrabenen Gewölbe.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Ah, das ist der Nachteil, dass ich mein ganzes Leben in der Scherbenwelt verbracht habe. Ich habe nicht den blassesten Schimmer, was das für Artefakte sind...\n\nUnd ein Tagebuch habt Ihr auch noch gefunden? \n\nWir sollten alles dem Drachenschuppenteam bringen, vielleicht wissen sie dort ja mehr.\n\n<Voraxian fällt auf, dass Ihr Euch die toten Hüter um ihn herum anseht.>\n\nAch die, auch wir haben uns ein wenig ausgetobt, während Ihr im Gewölbe wart. Aber keine Sorge, die Sache ist geregelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[73039] = { id = 73039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruheloser Tod", description = "Was könnte jemanden dazu bringen, so etwas zu tun...\n\nIch kann ein Ritual durchführen, um diesen armen Kreaturen den Übergang zu erleichtern. Nehmt diese Totems und platziert sie entlang des Flusses. Mit genügend Ankerpunkten sollte es mir gelingen, ihnen beim Übergang zu helfen.\n\nWir machen uns derweil auf die Suche nach einer Ritualstätte.", sourceObjective = "Platziert Ankertotems in der Ätzsäurenschlucht, damit Narvra ihr Reinigungsritual durchführen kann.", completion = "Danke, {name}. Gebt mir noch einen Moment. Wir werden gleich mit dem Ritual beginnen.\n\nHoffen wir, dass wir diesen Seelen Ruhe verschaffen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[73040] = { id = 73040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unordnung in die Ordnung bringen", description = "So was von unhöflich! Es stimmt schon, wir haben auch keine Geschenke mitgebracht, aber so begrüßt man doch keine Besucher! Solch schlimme Manieren sind unentschuldbar! Halunken! Taugenichtse! Grobiane!\n\n<Rupert hustet in seine Hand.>\n\nIch wollte eigentlich sagen, dass diese Hüter wohl eine Bedrohung darstellen. Jeder, der sich hier hineinwagt, könnte in Gefahr sein.\n\nKönntet Ihr dafür sorgen, dass dieser Ort sicherer wird, indem Ihr sie ausschaltet?", sourceObjective = "Eliminiert 6 rasende Hüter in den Begrabenen Gewölben.", completion = "Schöner Auftritt, {name}. Jetzt ist es hier viel sicherer. Diese Grobiane werden niemanden mehr belästigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73041] = { id = 73041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschnaufpause", description = "Danke für alles, was Ihr für uns getan habt.\n\nWir sind wieder auf die Beine gekommen, und Butterfinger hat eine Mahlzeit zubereitet.\n\nWir haben ein Mitglied verloren und sind alle noch erschüttert... Der Moralschub einer guten Mahlzeit würde uns ganz gut tun.\n\nMöchtet Ihr mitessen?", sourceObjective = "Esst gemeinsam mit dem Drachenschuppenteam in der Zaralekhöhle.", progress = "Danke, {name}. Wir können diese kleine Pause gut brauchen.", completion = "Die Rückgabe der Artefakte ist das Mindeste, das wir tun können. Und dass wir weitere Artefakte erforschen können, ist verlockend!\n\nVielen Dank für Eure Hilfe, {name}. Diese Möglichkeit der Erforschung ist eine große Sache für die Drachenschuppenexpedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[73042] = { id = 73042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Turm hoch hinaus", sourceObjective = "Untersucht den Blick von Neltharion in der Schwefelödnis.", progress = "Habt Ihr den Turm ausgespäht?", completion = "Wovon wurdet Ihr angegriffen?! Seid Ihr in Ordnung?\n\nWas habt Ihr gefunden? Ein weiteres Buch?\n\nTellywin, seht Euch das an!", sourceObjectiveStatus = "unverified-source-field" }
quests[73043] = { id = 73043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein grauenvolles Vermächtnis", description = "Wir müssen dafür sorgen, dass diese Kreaturen endlich Frieden finden.\n\nWenn Ihr dort unten seid und Voraxian unterstützt, erlöst bitte diese Kreaturen von ihren Leiden. Selbst wenn Ihr sie nur kurz von ihrer Existenz befreit, erleichtert Ihr ihnen ihre Last. In der Zwischenzeit kann Narvra ihr Ritual durchführen.", sourceObjective = "Eliminiert 10 geisterhafte Forscher und fehlgeschlagene Experimente in der Ätzsäurenschlucht.", completion = "Danke, {name}.\n\nEs ist absolut entsetzlich, was hier passiert ist... Und ich mache mir Sorgen um Voraxian.\n\nIch bin froh, dass Ihr an seiner Seite wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[73044] = { id = 73044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalogisierung des Horrors", description = "Ich... Ich muss Beweise für diesen Wahnsinn zu meinem Schwarm zurückbringen. Es könnte uns vernichten, aber meine Leute müssen davon erfahren. \n\nIch habe mir ein paar Katalogisierungskameras von Tellywin geliehen. Könnt Ihr mir helfen, diese Gräueltaten zu dokumentieren?\n\nIch kann Euch einen ähnlichen Schutz gewähren wie den, den ich im Gewölbe verlieh. Ich überlasse das Kämpfen Euch. Ich kann dem Leid, das mein Schwarm verursacht hat, nicht noch weiteres Leid hinzufügen. \n\nBringen wir das so schnell wie möglich hinter uns.", sourceObjective = "Nutzt die Katalogisierungskamera, um Bilder vom Entsorgungsort für die Experimente in der Ätzsäurenschlucht zu machen.", progress = "Ich kann nicht fassen, was hier stattgefunden hat...", completion = "Vielen Dank. Dass vor dem Fall meines Schwarms solche Gräueltaten begangen wurden... widert mich zutiefst an.\n\nIch werde unseren Anführern diese Bilder bringen. Wenn wir nicht aus unserer Geschichte lernen, sind wir dazu verdammt, sie zu wiederholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73045] = { id = 73045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleckenentfernung", description = "Wir können mit dem Ritual beginnen, wenn Ihr bereit seid.\n\nHelft mit, diese Geister zu erlösen.", sourceObjective = "Schließt das Reinigungsritual ab.", progress = "Wir müssen das Ritual zu Ende bringen, {name}.", completion = "Vielen Dank, {name}.\n\nNach Sytorians Übergang war es möglich, das Ritual durchzuführen und es zu vollenden. Mit der Zeit werden die letzten Überreste seiner Taten vergehen.\n\nIhr habt heute so vielen geholfen. Wir stehen für immer in Eurer Schuld. Als Nächstes sollten wir erst einmal zum Lager zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[73046] = { id = 73046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhleneskapaden", description = "Während wir darauf warten, dass Veritistrasz und Narvra das Lager wieder gesund pflegen, könnten wir einen kleinen Ausflug machen.\n\nIch habe auf unserem Weg hierher eine Höhle aufgespürt, und... ich möchte vielleicht ein wenig auf Erkundung gehen, um mich von dem abzulenken, was gerade passiert ist...\n\nWollt Ihr mitkommen?", sourceObjective = "Begleitet Rupert vom Drachenschuppenlager in der Zaralekhöhle.", completion = "Wie extrem unhöflich!\n\nWas soll das? Wir kommen gerade erst an, stellen uns höflich vor und schon greift man uns an!\n\nGrobiane!", sourceObjectiveStatus = "unverified-source-field" }
quests[73047] = { id = 73047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrestrisches Tunnelgraben", description = "Ich habe keine Lust mehr, länger an diesem Ort zu bleiben.\n\nWollt Ihr zurück ins Lager?", sourceObjective = "Kehrt ins Lager der Drachenschuppenexpedition in der Zaralekhöhle zurück.", completion = "Oh, alle scheinen wieder auf den Beinen zu sein! Wie wunderbar!\n\nUnd Butterfinger hat anscheinend ein regelrechtes Festmahl aufgetischt!", sourceObjectiveStatus = "unverified-source-field" }
quests[73052] = { id = 73052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalderakurven - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
