quests[73064] = { id = 73064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaubergeschmiedeter Schneemann" }
quests[73065] = { id = 73065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene-Insel-Eile - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[73069] = { id = 73069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhe für Sindragosa und Malygos", description = "Die Vorbereitungen sind jetzt abgeschlossen. Kalecgos und Alexstrasza sollten bald mit den verbleibenden Essenzen von Sindragosa und Malygos eintreffen.\n\nBeide haben einen grausamen Tod erlitten. Ich habe gehört, dass Malygos Alexstrasza mit seinem letzten Atemzug sogar noch verflucht hat.\n\nUnd Sindragosa... Sie wurde vor Tausenden von Jahren von Nelthar... von Todesschwinge getötet. Danach wurde sie vom Lichkönig auch noch wiederbelebt und von Abenteurern erneut getötet. Ich kann kaum erahnen, in welchem Zustand sich die Essenz befinden muss...\n\nVergebt bitte mein Geschwätz. Kalecgos und Alexstrasza sollten bald eintreffen.", sourceObjective = "Beobachtet, wie Kalecgos und Alexstrasza die Überreste von Sindragosa und Malygos zur Ruhe betten.", completion = "Danke, dass Ihr Senegos geholfen habt, {name}.\n\nEs ist Zeit, zu den Archiven zurückzukehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[73071] = { id = 73071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein legendäres Gebräu", description = "Die Legenden erzählen von einem Bier, das Neltharion einst selbst braute und das seither verloren gegangen ist! Wenn die Legenden wahr sind, und das sind sie ganz sicher, finden wir vielleicht das Rezept in diesem Gewölbe!\n\nIpfelkofer und ich haben drei Schlüssel für dieses Gewölbe gefunden, also wollten wir uns einmal umsehen. Hoffentlich wird unser Durst nach Entdeckung gestillt.\n\nStellt Euch vor, was in der Brauergemeinde los wäre, wenn wir dieses Rezept finden. Wir könnten das Bier beim nächsten Braufest präsentieren! Die erste Runde geht auf mich.", sourceObjective = "Findet 15 Rezeptseiten.", progress = "Habt Ihr das Rezept gefunden?\n\nIch wette, es ist ein Porter... Oder vielleicht ein Starkbier... Irgendwas Dunkles und leicht Bitteres.", completion = "Unsere Operation war erfolgreich! Jetzt, da wir das Rezept haben, brauchen wir die hier nicht mehr, also nehmt Euch, was Ihr wollt.\n\nAlso, wie sollen wir dieses Bier nennen? Der Schwarze Bitter? Das Dunkle Porter?\n\nWie auch immer, das war toll! Ich brauche was zu trinken.", sourceObjectiveStatus = "unverified-source-field" }
quests[73076] = { id = 73076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Insel", description = "Vor langer Zeit war die Insel unser Ausbildungsgelände. Jetzt ist es Zeit, zurückzukehren. Die Insel birgt vielleicht noch Geheimnisse unserer Vergangenheit.\n\nSchuppenkommandantin Glutthal ist vorausgegangen. Sie erwartet die Ankunft all jener, die uns helfen wollen. Wir brauchen alle Hilfe, die wir kriegen können, wenn wir auf der Insel Fuß fassen wollen. Sichere Reise.", sourceObjective = "Trefft Glutthal auf der Verbotenen Insel.", completion = "Ihr kommt vom Festland? Dann wurde unser Hilferuf gehört.\n\nUnsere Verbündeten kommen aus jedem Winkel der Inseln, aber unsere Operationsbasis ist alles andere als gesichert.\n\nKommt, {class}. Es gibt viel zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73077] = { id = 73077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mächtige Stich", description = "Entspannt Euch. Diese Splitterflamme ist lediglich vergiftet. Er wird nicht sterben. Wahrscheinlich nicht.\n\nEr wird nur Schmerzen erleiden.\n\n<Patroclosa sieht Euch an und seufzt dann.>\n\nWenn Ihr ihm dieses Schicksal ersparen wollt, könntet Ihr natürlich die Gallen von Quarzitsporenseglern sammeln, die hier im Tal leben. Die Gallen enthalten ein natürliches Gegengift, das sein Leid lindern würde. Ich werde meine Heilmagie ganz sicher nicht wirken, um einem Mörder zu helfen.\n\nUnd wenn Ihr schon dabei seid, könnt Ihr auch Lehmkappen mitbringen. Die werden ihm helfen, die Galle bei sich zu behalten. Ich bin trotzdem überzeugt, dass er diese Güte nicht verdient hat.", sourceObjective = "Sammelt 8 schwammige Lehmkappen und 6 Portionen Quarzitsporengalle.", progress = "Wir müssen alle unseren eigenen Weg finden. Ich wünschte nur, unserer wäre ein bisschen einfacher...", completion = "Ich hoffe, sie hat für sich die richtige Entscheidung getroffen. Geht mit Patri nicht zu hart ins Gericht. Seit sie Ekrati verloren hat, ist sie nicht mehr dieselbe.\n\n<Tezelari schafft es trotzdem, Euch anzulächeln.>\n\nWir sollten von hier an nur nach vorne blicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[73078] = { id = 73078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Sturmrisskrater-Rundflug" }
quests[73079] = { id = 73079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Morqutaufstieg" }
quests[73080] = { id = 73080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Nistklufttour" }
quests[73081] = { id = 73081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stressfrakturen", description = "Ein weiteres Mitglied der Splitterflammen wurde im Auftrag von Schuppenkommandantin Glutthal gefangen genommen. Amythora glaubt, es muss sich um einen Boten handeln.\n\nWir müssen entscheiden, was wir mit ihm machen. Bis dahin wäre es gut, wenn Ihr herausfindet, ob er wichtige Informationen hat.\n\nEr wird gut bewacht, also wird er sich auch nicht zur Wehr setzen. Einige Dracthyr in der Nähe haben ihre Hilfe angeboten. Sie meinten, sie wären Begleiter der Schuppenkommandantin! Und sie wussten genau, wie man mit Gefangenen der Splitterflammen umgeht.", sourceObjective = "Untersucht den gefangenen Boten der Splitterflammen.", progress = "Ihr wollt garantiert, dass ich rede, aber ich kann nicht.\n\nWas auch immer Ihr mir antut, Sarkareths Bestrafung wird tausendmal schlimmer sein.", completion = "Ihr... Ihr hättet das nicht tun müssen.\n\n<Der {race} hantiert mit seinen Fesseln herum.>\n\nIch bin trotzdem dankbar dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[73082] = { id = 73082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Südinselroute" }
quests[73083] = { id = 73083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Kalderakletterei" }
quests[73084] = { id = 73084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Verbotene-Insel-Eile" }
quests[73085] = { id = 73085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalte Füße", description = "Wenn Marithos und Amythora weglaufen und Abenteurer spielen wollen, ist das ihre Sache. Ich hingegen bin loyal.\n\n<Trotz seiner markigen Worte wirkt der Bote unsicher.>\n\nIhr habt keinen blassen Schimmer, wozu Sarkareth fähig ist, versteht Ihr?\n\nDurchsucht meine Sachen und zieht Eure eigenen Schlüsse, wenn Ihr wollt. Aber ich werde nichts sagen. Ich kann einfach nicht.", sourceObjective = "Durchsucht die Sachen des gefangenen Dracthyrs nach Hinweisen zu den Splitterflammen.", progress = "Habt Ihr etwas herausgefunden? Und warum seht Ihr so aus, als wärt Ihr in eine Rauferei verwickelt gewesen?\n\n...Oh. Verstehe. Das klingt sehr beunruhigend.\n\n<Marithos seufzt.>", completion = "Vielen Dank für alles, {name}. Ich nehme an, es wird im Zuge unseres Wiederaufbaus nicht der einzige Kampf bleiben.\n\nIch werde sehen, was ich den von Euch beschafften Informationen entnehmen kann.\n\nOh, und ich werde dafür sorgen, dass unser gefangener Freund sein Hornsignet zurückerhält. Ich bin mir seines Schicksals ungewiss, aber zumindest kann ich ihm helfen, seinen Seelenfrieden zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[73086] = { id = 73086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesunder Wettbewerb", description = "Unter Glutthals Führung wurden viele meiner Hortgefährten aufgenommen, aber zwischen den früheren Splitterflammen und den Dracthyr, die wir verletzt haben, gibt es weiterhin Spannungen.\n\nAber zum Glück habe ich einen Weg gefunden, diese Spannungen auf produktive Dracthyrart aufzulösen und die Bindung zwischen Rufern zu stärken. Sparring!\n\nKommt schon. Traut Euch ruhig! Zeigen wir diesen Rabauken, wie man einen Streit klärt.", sourceObjective = "Schlagt Amythora beim Sparring.", completion = "Gut gemacht! Diese Lektion werden sie nie vergessen. Und ich schätze, auch ich kann noch die eine oder andere Sache von Euch lernen. Aber lasst Euch deswegen Eure Flügel nicht zu Kopf steigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73089] = { id = 73089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist hinter der nächsten Tür?", description = "Wenn wir diese Gewölbe erforschen wollen, müssen wir mehr Türen öffnen! Und das bedeutet, wir brauchen mehr Schlüssel.\n\nVersucht, weitere Schlüssel auf der Verbotenen Insel zu finden. Jede neue Tür ist eine neue Chance!", sourceObjective = "Betretet das Gewölbe und öffnet 3 weitere Türen mit Gewölbeschlüsseln von Zskera.", completion = "Gut gemacht, mein Freund. Wir können hier so lange weiter alles erkunden, wie wir Schlüssel haben.\n\nIn ein paar Tagen erforschen bestimmt wir ein anderes Gewölbe. Die Neugier bringt mich noch um!", sourceObjectiveStatus = "unverified-source-field" }
quests[73090] = { id = 73090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedauern in Kristallsangwald", description = "Ich kann mir schon denken, was Lanigosa im Kristallsangwald vorhaben könnte, obwohl mir nicht klar ist, warum sie das auf sich genommen hat.\n\nDieser Wald birgt die Ruinen von Shandaral, einer ehemaligen Siedlung von Hochgeborenen und Schauplatz einer der ersten Kämpfe zwischen Sterblichen und dem blauen Drachenschwarm. Sollte Lanigosa wirklich im Kristallsangwald sein, kann das durchaus etwas mit Shandaral zu tun haben.\n\nBegebt Euch zu ihr, {name}, und versucht sie davon zu überzeugen, zu uns zurückzukehren.", sourceObjective = "Sprecht mit Lanigosa im Kristallsangwald.", completion = "Vergebt mir, {class}. Ich habe Euch mit einer gequälten Arkanerscheinung verwechselt.\n\n...Schaut mich nicht so an! Ihr glaubt ja gar nicht, wie leicht man hier draußen diesen Fehler begeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[73091] = { id = 73091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallsangwald", description = "Der blaue Drache Lanigosa stand den Sterblichen während des letzten Krieges gegen die Brennende Legion zur Seite. Dem Ruf zu den Inseln ist sie allerdings nicht gefolgt.\n\nOb ihr etwas zugestoßen ist? Oder hat sie sich einfach entschieden, nicht zurückzukehren? Egal, welche Gründe sie hat, Azuregos' Globus scheint anzuzeigen, dass sie zuletzt im Kristallsangwald gesehen wurde.", sourceObjective = "Sprecht mit Kalecgos.", completion = "Lanigosa war mir immer freundlich zu mir. Ich hoffe, es geht ihr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[73092] = { id = 73092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas wie Familie", description = "Kostet mal! Scaralesh Spezial! Als hungriger Dracthyr, der etwas Aufmunterung sucht, ist man hier genau richtig!\n\n<Scaralesh senkt die Stimme, als er Euch anspricht.>\n\nGanz unter uns, {name}? Unser Volk hat in letzter Zeit viel durchmachen müssen. Da braucht es etwas, das uns zu entspannen hilft und uns daran erinnert, dass wir immer füreinander da sind. Eine Mahlzeit mit der Familie könnte da genau das Richtige sein.\n\nRommen und ich kümmern uns ums Kochen. Bringt Ihr dann den hungrigen Dracthyr die Teller mit Essen?", sourceObjective = "Bringt Essensportionen zu den Dracthyr auf dem Fest in Weyrnruh.", completion = "Noch mehr hungrige Bäuche? Nein? Gut!\n\n<Scaralesh senkt die Stimme, als er Euch anspricht.>\n\nVielen Dank, {name}. So manchen {race} sehe ich heute zum ersten Mal seit langer Zeit wieder lächeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[73093] = { id = 73093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leere Stühle", description = "Ich möchte Euch nicht von den Festlichkeiten abhalten, aber leider fehlt jemand, der hier sein sollte.\n\nWir Dracthyr sollten alle zusammenkommen, Rathane aber scheint das anders zu sehen. Er war Anhänger der Splitterflammen genau wie wir. Und obwohl er ihnen nach den Ereignissen in Aberrus den Rücken gekehrt hat, kämpft er immer noch mit seiner Schuld. Er schien ziemlich gequält zu sein.\n\nWürdet Ihr nach ihm suchen? Und dafür sorgen, dass es ihm gut geht, und ihm sagen, dass er hier willkommen ist?", sourceObjective = "Findet Rathane.", completion = "Vor uns liegt noch eine Menge Arbeit, viele Wunden müssen geheilt werden.\n\n<Rathane schaut nieder auf das zerbrochene Hornsignet in seiner Hand.>\n\nAber wir können einander helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73094] = { id = 73094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Expedition", description = "Sarkareth wird für seine Verbrechen bezahlen.\n\n<Glutthal wappnet sich.>\n\nWir dürfen nicht zulassen, dass unter ihm und seinem verdrehten Bestreben noch mehr Leute leiden.\n\nWenn die Splitterflammen die Drachenschuppenexpedition bedrohen, müssen wir unseren Verbündeten zu Hilfe eilen.", sourceObjective = "Trefft Schuppenkommandantin Glutthal und Ebyssian beim Sturmrisskrater auf der Verbotenen Insel.", completion = "Zu viele mussten leiden. Zu viele ihr Leben lassen.\n\nGenug ist genug. Sarkareth ist verantwortlich. Und er wird dafür bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73107] = { id = 73107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendestein: Erster Bericht", description = "<Dieser Sendestein birgt uralte Worte in einem alten drakonischen Dialekt, die Adamanthia einst an Neltharion gerichtet hat.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Sendestein.", progress = "Was habt Ihr entdeckt?", completion = "Sie... Sie wussten es. Sie wussten, dass wir nicht gebrochen waren, und haben uns trotzdem in Stasis gehalten.\n\nIch werde das übersetzen lassen, damit es jeder lesen kann. Auf dass es zur Einsicht verhilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[73108] = { id = 73108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendestein: Die Gefangene", description = "<Dieser Sendestein birgt uralte Worte in einem alten drakonischen Dialekt, die Adamanthia einst an Neltharion gerichtet hat.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Sendestein.", progress = "Was habt Ihr entdeckt?", completion = "Raszageth hatte also eine Kerkermeisterin. Oder war Adamanthia unsere Kerkermeisterin?\n\nRätselhaft. Ich werde das übersetzen und den Bänden hinzufügen lassen, damit andere es lesen können. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[73109] = { id = 73109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empfangsstein: Letzte Warnung", description = "<Dieser Empfangsstein birgt uralte Worte in einem alten drakonischen Dialekt, die Neltharion einst gesprochen hat.>\n\n<Die Dracthyr-Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.", sourceObjective = "Bringt den Empfangsstein zu Schuppenkommandant Azurathel.", progress = "Was habt Ihr entdeckt?", completion = "Was? Wovon wollte Neltharion Adamanthia abhalten?\n\nIch werde das übersetzen und den Aufzeichnungen beifügen lassen. Gut, dass sich diese Nachrichten durch ihre Magie zeitlich nachvollziehen lassen.\n\nAber warum wurden sie nach ihrer Verwendung nicht zerstört?", sourceObjectiveStatus = "unverified-source-field" }
quests[73110] = { id = 73110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Experimente", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Sammelt einen Tagebucheintrag.", progress = "Konntet Ihr irgendetwas von Interesse finden, {name}?", completion = "Ah! Exzellent. Weitere Hinweise zu unserer Vergangenheit.\n\n<Glutdresch liest sich den Tagebucheintrag durch und wird dabei immer wütender.>\n\nExperimente?! Wir waren für sie nichts als... \"Dinge\"?! Und sie konnten uns nicht kontrollieren, weshalb sie... Hrrrr!\n\nDanke, dass Ihr mir das gebracht habt. Wir müssen das übersetzen lassen, damit andere es auch lesen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[73113] = { id = 73113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Relikte", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Sammelt einen Tagebucheintrag.", progress = "Konntet Ihr irgendetwas von Interesse finden, {name}?", completion = "Ordnung. Immer geht es um die Durchsetzung von Ordnung.\n\nVielen Dank, {name}. Das kommt zu den Übersetzungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73114] = { id = 73114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Die Horte", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Sammelt einen Tagebucheintrag.", progress = "Konntet Ihr irgendetwas von Interesse finden, {name}?", completion = "Es ist ziemlich verstörend, das zu lesen. Selbst, wenn man weiß, was passiert ist und wie alles geendet hat.\n\nIch werde es für die anderen übersetzen lassen. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[73115] = { id = 73115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Stille", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Tagebucheintrag.", progress = "Das könnte sich als äußerst aufschlussreich erweisen.", completion = "Eine Stille, die Tausende von Jahren gedauert hat, und das alles nur, wegen eines einzelnen Befehls.\n\nWenn ich daran denke, dass ich so einem Befehl bis in den Tod gefolgt wäre, ohne ihn jemals zu hinterfragen...\n\nDanke, dass Ihr mir diesen Tagebucheintrag gebracht habt, {name}. Der kommt zu den anderen Übersetzungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73119] = { id = 73119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahrer Hort von Welpenhappen", description = "Agapanthus sagt, neue Happenbestellungen sind bereit zum Abholen, aber wir beide haben alle Hände voll zu tun.\n\nKönntet Ihr losrennen und die Happen einsammeln, während wir uns um die Welpen kümmern?", sourceObjective = "Sammelt Happenbestellungen von Verkäufern in Valdrakken.", progress = "Zum Glück müssen wir die Happen nicht alle selbst essen, wir müssen nur wissen, was die Welpen wollen und das zur Verfügung stellen. Sie wollen ganz klar Käse und Salzkekse.", completion = "Danke, dass Ihr mehr Happen gebracht hat. Das sollte ihren Hunger eine Weile stillen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73120] = { id = 73120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appetitliches Nachspiel", description = "Die heutigen Aktivitäten wurden von einer spontanen Essensschlacht unterbrochen, die mehrere ungewollte Besucher angezogen hat!\n\nHelft bitte beim Saubermachen.", sourceObjective = "Helft in der Krippe \"Kleinschuppe\" beim Aufräumen.", progress = "Es ist schon interessant, Hausmeister, Erzieher und Aufpasser zu sein, wobei das wohl allen Leuten in der Krippe so geht.", completion = "Ich wünschte einfach, dass hier wenigstens mal für ein paar Minuten alles sauber bleibt!\n\nSo oder so, vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[73124] = { id = 73124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horterverhalten", description = "Die Welpen verbringen gerne Zeit mit Sir Pringisch, doch ihr Herumgetrampel hat seinem Gehege ordentlich zugesetzt.\n\nKönntet Ihr bitte noch etwas Gestrüpp für ihn besorgen? Und wenn Ihr schon dabei seid, er könnte auch ein hübsches neues Spielzeug gebrauchen. Und Räucherwerk.\n\nWir dürfen nicht zulassen, dass hier alles verfällt.", sourceObjective = "Sammelt Materialien für Sir Pringischs Unterkunft.", progress = "Neben dem speziellen Grünton ist es Sir Pringisch eigentlich nur wichtig, dass sein Bereich mit natürlichen Materialien ausgekleidet ist.", completion = "Das Gehege sieht wunderbar aus, {name}.\n\nDas sollte Sir Pringisch ein Weilchen halten, bis die Welpen hier wieder alles durcheinanderbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73126] = { id = 73126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunst und Handwerk und Bäder", description = "Unsere Kunst- und Handwerksaktivitäten heute sind etwas aus dem Ruder gelaufen. Einer der Welpen hat seine Bürste verzaubert und der Rest hat es ihm dann gleichgetan. Jetzt ist hier alles voller Farbe.\n\nMacht Ihr bitte die Krippe sauber, während wir die Farbe von den Welpen waschen.", sourceObjective = "Helft in der Krippe \"Kleinschuppe\", Farbe zu beseitigen.", completion = "Ihr kommt genau zur rechten Zeit, {name}. Vielen Dank. Da waren sechs Hände von Nöten.\n\nUnd jetzt müssen wir noch Sir Pringisch zurechtweisen, dass er dem Verhalten der Welpen nachgegeben hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[73128] = { id = 73128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht auf der Seite", sourceObjective = "Helft in der Krippe \"Kleinschuppe\", die Bösewichte verschiedener Geschichten zu bekämpfen.", progress = "Ich habe diese Geschichten mittlerweile so oft gehört. Jeden Tag dagegen zu kämpfen, ist, milde ausgedrückt, äußerst anstrengend.", completion = "Als die Welpen erfahren haben, dass wir bestimmte Teile der Geschichte zum Leben erwecken können, haben sie darauf bestanden, dass von nun alle Geschichten an so erzählt werden.\n\nDanke, dass Ihr uns eine kleine Verschnaufpause verschafft habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[73130] = { id = 73130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenkritzeleien mit Gefieder", description = "Unsere Lernstunde zu magischen Runen hat heute scheinbar ihre ersten Früchte getragen. Die Welpen sind ganz versessen darauf, entgegen aller Vernunft, überall ihre Runen zu üben.\n\nDiese Faszination hat zu einer recht interessanten Spielstunde geführt! Helft uns bitte dabei, die Spielzeuge wieder an den richtigen Ort zu bringen und bannt dabei alle Runen, denen Ihr begegnet.", sourceObjective = "Helft in der Krippe \"Kleinschuppe\" beim Aufräumen.", completion = "Danke für Eure Hilfe, {name}. Dieser Sandkasten hat seinen eigenen Willen!\n\nWir werden unser Bestes tun, damit die Welpen ihn nicht nochmal mit ihren Runen durcheinanderbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73131] = { id = 73131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elegante Verkleidungen", sourceObjective = "Findet Belastrasza und ihre Freunde in Valdrakken.", completion = "Das hat Spaß gemacht! Und ich habe auch schon Inspiration für meine nächsten Verkleidungen. Ich mache mich direkt an die Arbeit!\n\nIhr dürft nun gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[73132] = { id = 73132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absuchen der Stapel", sourceObjective = "Findet Zaleth und seine Freunde in Valdrakken.", completion = "Ich muss noch an meiner Strategie feilen. Ihr seid richtig gut im Finden!\n\nIch liebe Verstecken! Lasst uns bald nochmal spielen!", sourceObjectiveStatus = "unverified-source-field" }
quests[73133] = { id = 73133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemütliche Tarnung", description = "<Posidriss gähnt.>\n\nIch kann einfach nicht schlafen. Lasst uns stattdessen ein Spiel spielen!\n\nVielleicht gibt es da draußen irgendwo ein gemütliches Versteck. In der Stadt findet Ihr mich bestimmt nie!", sourceObjective = "Findet Posidriss und seine Freunde in Valdrakken.", completion = "Danke, {name}! Das hat echt Spaß gemacht!\n\nIch wünschte nur, ich würde etwas Schlaf bekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[73134] = { id = 73134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Eskapaden", description = "Ha... HATSCHI!\n\nEntschuldigung. Wollt Ihr Verstecken spielen? Ich habe neue Verstecke gefunden und hätte Lust auf eine Runde!\n\nHoffentlich bereiten mir meine Allergien keine Probleme!", sourceObjective = "Findet jeden Zhusa in Valdrakken.", completion = "Wow, die anderen Zhusas hatten echt gute Verstecke! Ich habe noch einiges zu lernen.\n\nDanke, dass Ihr etwas Zeit mit mir verbracht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[73135] = { id = 73135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidianvertuschung", sourceObjective = "Findet Ruszi und ihre Freunde in Valdrakken.", completion = "Ihr habt uns alle gefunden! Ich werde schon besser im Verstecken. Ich kann es kaum erwarten, noch mal mit Euch zu spielen!\n\n<Ruszi macht eine Pirouette.>\n\nDas hat richtig viel Spaß gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[73137] = { id = 73137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren der Flamme", description = "\"Er erwartet Euch in der Dunkelheit\"?\n\n<Glutthal kneift argwöhnisch die Augen zusammen.>\n\nIch weiß, wo Sarkareth ist.\n\nIch brauche Eure Hilfe, um ihn zur Rechenschaft zu ziehen. Wenn Ihr wollt, könnt Ihr noch etwas hierbleiben und diese Ruinen durchstöbern, doch ich glaube, dass wir gerade wichtigere Dinge zu tun haben. Falls Ihr bereit seid, all dem ein Ende zu setzen, dann folgt mir.\n\nIch begebe mich zur Drachenschädelinsel.", sourceObjective = "Trefft Schuppenkommandantin Glutthal auf der Drachenschädelinsel.", completion = "Ich wusste, Ihr würdet kommen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[73139] = { id = 73139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte aus der Tiefsee", description = "Bedrohungen aus dem Meer sind wir gewohnt. Aber manche Feinde hätten sich hier nie einnisten dürfen.\n\nIm Osten haben sich Naga auf den Stränden und in den Buchten breitgemacht. Sie haben Vorräte mitgebracht. Wenn wir die hiesige Nagapopulation eindämmen und ihre Vorräte sicherstellen könnten, würde das unsere Chancen verbessern, hier zu überleben.\n\nDer Plan lautet wie folgt: Holt Euch ihre Vorräte aus Truhen oder von ihren Leichen und tötet den Anführer. Es geht hier ums Überleben!", sourceObjective = "Tötet Naga der Weitenschuppen und sammelt ihre Vorräte.", progress = "Habt Ihr die Vorräte gesammelt?", completion = "Vielen Dank, dass Ihr Wellen an Naga erledigt habt. Ihre Vorräte werden uns sicher helfen, unser Lager zu unterstützen, damit wir hier eine Heimat finden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[73140] = { id = 73140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Krater stürmen", description = "Die Primalisten haben in den Sturmrisskrater verlegt. Sie erwecken dort Elementare und beuten das Land aus.\n\nSie müssen ohne langes Zaudern und entschieden angegangen werden. Dezimiert sie, zerstört ihre Totems. Helft uns, die Verbotene Insel für die Dracthyr, Tuskarr und alle, die hier eine Heimat suchen, sicherer zu machen.", sourceObjective = "Tötet Primalisten im Sturmrisskrater.", completion = "Gut gemacht. Ihr habt ihren Plänen für die Verbotene Insel einen schweren Rückschlag verpasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[73141] = { id = 73141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewig brennende Glut", description = "Für Wärme zu sorgen, beschäftigt uns andauernd hier. Wir möchten nicht einfach alles verheizen, was wir mitgebracht haben, und sammeln nicht gerne Treibholz an Stränden, wo Feinde lauern. Viel zu riskant!\n\nDie Primalisten tragen aber quasi ihr eigenes Feuer bei sich.\n\nNehmt ihre ewig brennende Glut, wenn Ihr die mächtigen Feuerprimalisten tötet, und bringt sie her. Wir werden sie für einen guten Zweck nutzen.", sourceObjective = "Sammelt ewig brennende Glut von mächtigen Feuerprimalisten im Belagerungshort.", progress = "Ewig brennende Glut könnte uns das ganze Jahr über warm halten.", completion = "Perfekt! Damit wird uns auch in den kältesten Nächten warm sein. Sogar bei schlechtem Wetter wird uns das helfen, die Kochfeuer heiß zu halten.\n\nHabt Dank! Möget Ihr bei uns immer wärmstens empfangen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[73142] = { id = 73142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blau und blau geschlagen", description = "Malygos ließ Streitkräfte zurück, um uns zu bewachen, während wir schliefen. Er ist fort, aber seine Schergen sind noch hier und machen uns allen das Leben schwer.\n\nSpäher haben sie dabei beobachtet, wie sie mit arkanen Fokussen hantiert haben. Ich glaube, die könnten wir besser gebrauchen. Geht welche beschaffen. Die Sicherheitsstreitkräfte werden das nicht kampflos hinnehmen, aber das ist für Euch ja kein Problem, oder?\n\n<Glutdresch schnaubt.>\n\nVielleicht verstehen sie ja den Wink mit dem Zaunpfahl und verschwinden.", sourceObjective = "Sammelt arkane Fokusse von den blauen Sicherheitsstreitkräften an der Stätte des alten Weyrn.", progress = "Habt Ihr die Fokusse gesammelt?", completion = "Was für eine Erleichterung. Danke. Jetzt können wir nachts alle etwas besser schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73146] = { id = 73146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneidender Wind", sourceObjective = "Besiegt Vortex in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[73147] = { id = 73147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsteter Boden", sourceObjective = "Besiegt Beben in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[73148] = { id = 73148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennbare Gewächse", sourceObjective = "Besiegt Lauffeuer in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[73149] = { id = 73149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochwasserwarnung", sourceObjective = "Besiegt Fluss in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[73151] = { id = 73151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapeau!" }
quests[73155] = { id = 73155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergessene Ring", description = "<Der Ring weist ungewöhnliche Zeichen auf. Er könnte einen von den Dracthyr im Morqutdorf interessieren.>", sourceObjective = "Bringt den Ring zu Forscher Imareth im Morqutdorf.", completion = "Oh! So ein Relikt habe ich seit der Zeit vor unserem Erwachen nicht mehr gesehen! Das ist ein besonderer Ring, der offensichtlich von Neltharions Schmieden hergestellt wurde.\n\nIhr solltet ihn behalten. Führt ihn stets mit Euch. Er könnte Euch noch nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[73156] = { id = 73156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Viridia", description = "Ich übergebe Euch in Viridias Obhut. Sie arbeitet mit den Heilschwingen im Morqutdorf daran, einen sicheren Ort für die Dracthyr, Tuskarr und unsere anderen Verbündeten auf der Insel zu errichten.\n\nWir haben hier ein Zuhause... und ich... ich muss etwas nachdenken. Ich bin dankbar, dass Ihr mich während dieser Prüfung begleitet habt.\n\nEs ist noch nicht vorbei. Wenigstens weiß ich, dass ich auf Euch zählen kann, wenn wir uns Sarkareth das nächste Mal stellen. Vielen Dank.", sourceObjective = "Trefft Euch mit Viridia im Morqutdorf auf der Verbotenen Insel.", completion = "Willkommen zurück, {name}. Euer Gesichtsausdruck sagt mir, dass es nicht einfach war.\n\nIch bin freue mich nicht darauf, mich noch einmal mit Sarkareth herumschlagen zu müssen, aber wir werden das nächste Mal bereit sein. Vorerst haben wir Dringenderes zu tun. Wir werden nicht fertig sein, bis die Insel für alle sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[73157] = { id = 73157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barmherzige Schwingen", description = "Nachdem die Stürme nachgelassen haben, haben wir Spähtrupps entsendet, um die Insel zu erkunden.\n\nEinige davon sind nicht zurückgekehrt. Wir befürchten, dass sie womöglich unbekannten Gefahren zum Opfer gefallen sind.\n\nKönntet Ihr die Insel nach ihnen absuchen? Sobald Ihr sie gefunden habt, nutzt das Heilersignal, um einen Heiler zu rufen.", sourceObjective = "Helft Dracthyrspähern an drei Orten auf der Verbotenen Insel.", completion = "Ich bin dankbar für die Hilfe, die Ihr unseren Spähern geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[73159] = { id = 73159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundung unserer Vergangenheit", description = "Mit Eurer Hilfe können wir die Geheimnisse dieses Landes jetzt eingehender ergründen.\n\nDie Gewölbe von Zskera liegen hier in der Nähe. In diesen großen unterirdischen Kammern hat Neltharion diverse Schätze und vergessene Forschungsergebnisse gelagert. Es würde uns sehr weiterhelfen, wenn Ihr sie erkundet.\n\nBitte reist mit Tacha und Jeb und unterstützt sie wenn nötig.", sourceObjective = "Trefft Euch mit Jeb und Tacha am Eingang zu den Gewölben von Zskera.", completion = "Hinter diesen riesigen Türen liegen zahlreiche Kammern, die es zu erforschen gilt. Seid Ihr bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[73160] = { id = 73160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helfende Hände und Klauen", description = "Mitglieder der Drachenschuppenexpedition kommen her, um dabei zu helfen, die Ruinen dieser Insel zu erforschen. Ihre Bemühungen könnten uns helfen, weitere Einzelheiten über unsere Vergangenheit zu sammeln.\n\nMeine Späher haben drei von ihnen an der Scharfschuppenküste gesehen, die dort Schiffbruch erlitten haben. Seht, ob Ihr ihnen helfen könnt, das Dorf wohlbehalten zu erreichen.", sourceObjective = "Helft Jeb, Tacha und Wulferd an der Scharfschuppenküste.", progress = "Kann man gefahrlos zum Morqutdorf reisen?", completion = "Dank Eurer Hilfe sind Jeb und ich in Sicherheit. Und unsere Vorräte auch!\n\nEin Fischer der Tuskarr ist bereit, uns zum Morqutdorf mitzunehmen. Hoffentlich sehen wir uns bald dort.", sourceObjectiveStatus = "unverified-source-field" }
quests[73169] = { id = 73169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, das Mondfest zu feiern. Der Ort, an dem Ihr hier in Sturmwind die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests in Sturmwind.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[73170] = { id = 73170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, das Mondfest zu feiern. Der Ort, an dem Ihr hier in Orgrimmar die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Tal der Weisheit in Orgrimmar.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[73171] = { id = 73171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues Aussehen erhalten: Maiev", progress = "Wendet eine Rumble-Folie auf Eure Warcraft Rumble-Miniatur an und erhaltet ein neues Aussehen!", completion = "Herzlichen Glückwunsch! Eure Miniatur von Maiev hat jetzt ein zusätzliches Aussehen!" }
quests[73172] = { id = 73172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Älteste der Shikaar", sourceObjective = "Euer Geist steckt voller Leben, junger {class}. Ich freue mich über den Respekt, den Ihr mir zollt, und gebe Euch dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[73173] = { id = 73173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch neueres Aussehen erhalten: Maiev", progress = "Wendet eine weitere Rumble-Folie auf Eure Warcraft Rumble-Miniatur an und erhaltet ein NOCH neueres Aussehen!", completion = "Herzlichen Glückwunsch! Eure Miniatur von Maiev hat jetzt ein zusätzliches Aussehen. Besser geht es nicht!" }
quests[73174] = { id = 73174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues Aussehen erhalten: Sneed", progress = "Wendet eine Rumble-Folie auf Eure Warcraft Rumble-Miniatur an und erhaltet ein neues Aussehen!", completion = "Herzlichen Glückwunsch! Eure Miniatur von Sneed hat jetzt ein zusätzliches Aussehen!" }
quests[73175] = { id = 73175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch neueres Aussehen erhalten: Sneed", progress = "Wendet eine weitere Rumble-Folie auf Eure Warcraft Rumble-Miniatur an und erhaltet ein NOCH neueres Aussehen!", completion = "Herzlichen Glückwunsch! Eure Miniatur von Sneed hat jetzt ein zusätzliches Aussehen. Besser geht es nicht!" }
quests[73178] = { id = 73178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finger weg von unseren Sachen!", description = "Die Eisenfluträuber haben von Dracthyr und Tuskarr gleichermaßen gestohlen. Sie nehmen alles, was sie in die Finger bekommen. Für sie ist alles nur Beute!\n\nHolt unsere gestohlenen Waren zurück und sorgt dafür, dass sie es bereuen, jemals hergekommen zu sein.", sourceObjective = "Besiegt Eisenfluträuber und holt gestohlene Waren zurück.", progress = "Habt Ihr den Piraten eine Lektion erteilt?", completion = "Das wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[73179] = { id = 73179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppokalypse, jetzt!", description = "Die Eisenfluträuber meinen, sie könnten hier hersegeln und die Kontrolle über die Inseln an sich reißen. Sie haben offenbar keine Ahnung, mit wem sie es zu tun haben. Unsere lieben Morqut werden Euch ein Transportmittel zur Verfügung stellen und wir Dracthyr die... Munition.\n\n<Glutdresch grinst.>\n\nFusethrian versucht schon eine Weile, zu kochen wie die Tuskarr. Mal hat er Erfolg, mal weniger. Bittet ihn einfach um seine instabileren Erzeugnisse. So können wir zwei Fliegen mit einer Klappe schlagen, indem wir dieses Gefahrgut entsorgen und gleichzeitig die Piraten vertreiben!", sourceObjective = "Besiegt Eisenfluträuber, um ihre Invasion zurückzuschlagen.", progress = "Habt Ihr diese Piraten gelehrt, sich aus unseren Gewässern fernzuhalten?", completion = "Hehe. Ich liebe den Geruch von suppenbasierter Munition am Morgen. Wie nach Sieg riecht das.", sourceObjectiveStatus = "unverified-source-field" }
quests[73181] = { id = 73181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulden begleichen", description = "Ich hoffe sehr, dass wir den Baron das letzte Mal gesehen haben. Um ehrlich zu sein, respektiere ich seinen Machtsitz im Schlingendorntal.\n\nWir haben Glück, dass Zeros noch am Leben ist. Er muss vor all diesem Ärger eine sehr gute Beziehung mit dem Baron gepflegt haben, sonst hätte er nicht so viel Zeit bekommen.\n\nKehren wir zu den Archiven zurück.", sourceObjective = "Kehrt zu den Azurarchiven zurück.", completion = "Diese Mission hat mir viel abverlangt, {name}. Lasst mich eine Weile ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73183] = { id = 73183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wollt Ihr ein Spiel spielen?", description = "<Ihr öffnet eine gekritzelte Notiz.>\n\nHallo, <Kollege/Kollegin>! Ich bin Mizzen, und wie man hört, seid Ihr gut im Finden von Dingen.\n\nWisst Ihr, ich spiele in letzter Zeit immer dieses neue Spiel namens Warcraft Rumble, aber mir sind die Münzen ausgegangen.\n\nWarum treffen wir uns nicht? Dann sage ich Euch, wo man welche findet.", sourceObjective = "Sprecht mit Mizzen in Valdrakken.", completion = "Hallo, schön, dass Ihr es geschafft habt.\n\nIhr müsst Euch diesen Automaten anschauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[73188] = { id = 73188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das besudelte Banner", description = "So lange es Magie gab, gab es auch jene, die sie für üble Zwecke einsetzen wollten.\n\nIch bin nicht sicher, welchen Groll diese abtrünnigen Magier hegen, dass Surigosa sie jetzt jagt, aber ich bin geneigt, in dieser Sache ihrem Urteil zu vertrauen. Gehen wir zu ihr, {name}, vielleicht können wir das Problem mit diesen Magiern lösen und gleichzeitig Surigosa überzeugen, zurückzukommen.", sourceObjective = "Findet Surigosa in Theramore.", completion = "Grüße, Sterblicher. Ihr und Eure Gefolgsleute kommt gerade rechtzeitig, um mir bei der Vernichtung dieser missgünstigen Magier zuzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73189] = { id = 73189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schätze des Horts", description = "Zum Glück seid Ihr hier. Käfer haben den Unterstützungshort befallen, also sind wir eilig geflohen. Das bedeutet, wir mussten viele Vorräte zurücklassen.\n\nUnd jetzt haben wir viele verletzte Forscher und könnten gut diese Vorräte gebrauchen! Könnt Ihr uns helfen?\n\nIhr müsst so viel retten, wie Ihr könnt. Nehmt Euch nur vor dem Gift in Acht.", sourceObjective = "Sammelt 6 Heilervorräte im Unterstützungshort.", progress = "He, habt Ihr die Vorräte zurückholen können?", completion = "Den Aspekten sei Dank! Diese Vorräte werden uns wieder auf die Beine bringen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[73190] = { id = 73190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Verseuchung", description = "Die Heilschwingen brauchen Zugang zum Unterstützungshort, aber es wimmelt weiterhin von den giftigen Käfern, die ihn befallen haben.\n\nViridia wüsste es bestimmt zu schätzen, wenn wir helfen, dieses Ungeziefer auszumerzen.", sourceObjective = "Tötet Käfer in der Kaldera der Heiler.", completion = "Wir merzen den Befall aus, Stück für Stück. Jedes bisschen hilft. Irgendwann werden diese Käfer endgültig verschwunden sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[73191] = { id = 73191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenbändigung", description = "Dieselben Gifte, die den Unterstützungshort verseuchen, wirken sich auch auf die wanderden Wasserschlangen aus.\n\nWir müssen die Schlangen wieder in ihre ursprünglichen Gewässer umsiedeln. Wenn wir das nicht schaffen, wird diese invasive Art die Umwelt zerstören.\n\nIch kann Euch einen freundlichen Wasserelementar leihen, der Euch hilft, die Schlangen zu transportieren. Zu ihrer Sicherheit wie auch Eurer.", sourceObjective = "Siedelt 6 giftige Wasserschlangen in die Becken der Kaldera der Heiler um.", completion = "Großartig! Wir machen gute Fortschritte, die Kaldera der Heiler wieder mit Leben zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73192] = { id = 73192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefiederter Freund", description = "Das Schmuckstück scheint eine Art Nobelgartendekoration zu sein. Es sollte vermutlich zum Fest in Goldhain zurückgebracht werden.", sourceObjective = "Bringt den Nobelgartenschmuck zu Zinnia Brooks in Goldhain.", completion = "Ah, danke, dass Ihr das zurückgebracht habt. Ich kümmere mich darum, dass alle gestohlenen Dekorationen wiederhergestellt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[73194] = { id = 73194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus nächster Nähe", description = "Die großen Protodrachen gehören zu den gefährlichsten Kreaturen der Verbotenen Insel.\n\nDie sind nicht leicht zu erledigen, aber wir haben vielerlei Waffen in unserem Arsenal.\n\nNehmt diesen Harpunenspeer. Wenn ein Protodrache Euch in sein Maul bekommt, müsst Ihr mit Zähnen und Klauen um Euer Leben kämpfen.\n\nEs ist nicht leicht, aber ich weiß, dass Ihr das schafft.", sourceObjective = "Tötet einen Protodrachen mit dem Prototötungsspeer.", completion = "So macht man das! Wenn der Tod einen buchstäblich gepackt hat, fühlt man sich erst richtig lebendig.", sourceObjectiveStatus = "unverified-source-field" }
quests[73196] = { id = 73196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarecgosas letzte Ruhe", description = "{name}, wartet einen Moment.\n\nBevor Ihr geht, gibt es noch eine Sache, die erledigt werden muss. Es gibt noch ein Mitglied meiner Sippe, das eine letzte Ruhe verdient.", sourceObjective = "Sprecht mit Kalecgos über Tarecgosa.", completion = "Es fühlt sich an, als würde ich einem Teil meiner selbst Lebwohl sagen, aber es muss sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[73197] = { id = 73197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlose Liebe", description = "Neben einem geeigneten Medium, das Tarecgosas Seele während des Rituals aufnehmen kann, brauchen wir genug magische Essenz, um die Blume zu erden. Der bronzene Drachenschwarm war an der Erschaffung des Stabs in Euren Händen beteiligt, also sollten wir am besten erneut seine Magie verwenden.\n\nEtwas Sand aus dem Temporalen Konflux sollte sich perfekt eignen. Achtet aber darauf, dass er zur magischeren Art gehört.", sourceObjective = "Sammelt vergänglichen Sand vom Temporalen Konflux.", progress = "Wie verläuft die Suche nach dem Sand?", completion = "Zeit ist selbst dann launisch, wenn sie richtig fließt. Ich verstehe nicht, wie meine Art sie meistern kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[73198] = { id = 73198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst sie nicht", description = "Der Stab wurde aus dem Ast eines Weltenbaums geschaffen, also muss das Medium, das die Seele aufnimmt, etwas Vergleichbares sein. In den widrigen Bedingungen von Vakthros gibt es vielleicht eine Blume, die hartnäckig genug ist, um dort zu wachsen.\n\nAber aus diesen Gründen wird sie zerbrechlich sein. Findet sie und bringt sie zu einem der Haine des grünen Drachenschwarms, um sie zu stärken.", sourceObjective = "Pflückt eine Manaherzblume und bringt sie zum Uralten Zweig, damit sie erblüht.", progress = "Wart Ihr fündig? Sie wächst nur sehr selten.", completion = "Die Blume wächst nur unter bestimmten Bedingungen und aus diesem Grund enthält sie eine Menge magische Energie. Das sollte das perfekte Medium für Tarecgosa sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[73199] = { id = 73199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsodie in Blau", description = "Es ist Zeit. Ich kann dies nicht weiter hinausschieben.\n\nSagen wir Lebwohl.", sourceObjective = "Helft Kalecgos dabei, Tarecgosa zur Ruhe zu betten.", completion = "<Kalecgos ist einen Moment still.>\n\nHabt Dank, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[73221] = { id = 73221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein klarer Verstand" }
quests[73226] = { id = 73226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenschädelbank", description = "Die Fische könnten etwas besser beißen, meint Ihr nicht?\n\nDa kommt mir eine Idee. Der Legende nach waren diese Seen und Flüsse nicht immer voller Fische. Angeblich wurden diese Wasserlöcher mit Fischen bestückt, als die Drachen darüber segelten und sie fallen ließen! Könnt Ihr das glauben?\n\nVielleicht könntet Ihr es mit Eurem Drachen mal versuchen?", sourceObjective = "Sammelt Fische, um das Angelloch zu bestücken, und besteigt Euren Drachen, um sie von oben abzuwerfen.", progress = "Habt Ihr die Fische bereits abgeworfen?", completion = "Ha! Die Legenden sind wahr, fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[73227] = { id = 73227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jadewald", description = "Die Tochter von Malygos und Saragosa, Kirygosa, überlebte die Wirren des Nexuskriegs, der ihr Leben ins Chaos stürzte und ihr die Familie nahm.\n\nIn der Folge suchte sie den ewigen Sommer des Schlingendorntals. Sie fand Wärme, aber kaum Frieden, und reiste weiter nach Morgenblüte, einem kleinen Dorf im Jadewald.\n\nDer blaue Drachenschwarm würde sich über ihre Rückkehr freuen.", sourceObjective = "Sprecht mit Kalecgos, um mehr zu erfahren.", completion = "...Kiry. Ja, ich weiß, wo sie ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[73371] = { id = 73371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues Aussehen erhalten: Nachtelfenjägerin", progress = "Wendet eine Rumble-Folie auf Eure Warcraft Rumble-Miniatur an und erhaltet ein neues Aussehen!", completion = "Herzlichen Glückwunsch! Eure Miniatur der Nachtelfenjägerin hat jetzt ein zusätzliches Aussehen!" }
