quests[73398] = { id = 73398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu forsch voran", description = "Unsere Frontkämpfer sind zu angriffslustig in eine Festung der Splitterflammen vorgestoßen und brauchen jetzt Hilfe. Wir müssen Euch reinschicken, um sie rauszuholen.\n\nHelft ihnen, da rauszukommen. Entweder mit Eurer Magie oder diesen Heilgebräuen von Viridia. Und wenn Ihr schon dabei seid, dezimiert die Splitterflammen gleich etwas. Sie haben es verdient.", sourceObjective = "Tötet Splitterflammen und heilt verletzte Dunkelkrallen und Obsidianwächter.", completion = "Es ist schön, unsere Kämpfer wieder wohlbehalten hier zu sehen, auch wenn ihr Stolz vielleicht gelitten hat. Für das, was kommt, brauchen wir jeden einzelnen Soldaten.", sourceObjectiveStatus = "unverified-source-field" }
quests[73399] = { id = 73399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach blauen Drachen", description = "Danke für Eure Hilfe bisher, {name}. Es gibt noch mehr blaue Drachen, die wir finden müssen.\n\nIch überlasse Euch die Ehre, das nächste Ziel auszusuchen.", sourceObjective = "Wählt ein Gebiet aus, in dem Ihr nach vermissten blauen Drachen suchen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[73404] = { id = 73404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene blaue Drachen", description = "Die Azurarchive werden dank Eurer Hilfe immer lebendiger.\n\nWählt den Ort aus, den Ihr als Nächstes untersuchen wollt.", sourceObjective = "Wählt ein Gebiet aus, in dem Ihr nach vermissten blauen Drachen suchen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[73405] = { id = 73405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Pärchen blauer Drachen", description = "Ich bin für Eure Hilfe dankbar, {name}. \n\nWo wollt Ihr als Nächstes nachsehen?", sourceObjective = "Wählt ein Gebiet aus, in dem Ihr nach vermissten blauen Drachen suchen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[73406] = { id = 73406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte vermisste blaue Drache", description = "Es gibt nur noch einen blauen Drachen, den wir finden müssen, {name}.\n\nBringen wir das zu Ende.", sourceObjective = "Wählt ein Gebiet aus, in dem Ihr nach vermissten blauen Drachen suchen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[73408] = { id = 73408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschnüffelungen!" }
quests[73550] = { id = 73550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honigfrostmet", description = "Na dann, da wir nun etwas freundlichere Beziehungen haben und ein bisschen was über die Winterpelze wissen, ist es an der Zeit, auf ordentliche Zwergenart Freundschaft zu schließen.\n\nWas könnte eine bessere Freundschaftsgeste sein, als ein starkes Getränk, um die Kälte zu vertreiben? Zwerge und auch Furbolgs haben eine lange Geschichte der Brauerei, also können wir es als eine Art Kulturaustausch betrachten!\n\nIch habe etwas südlich von hier ein paar ordentlich aussehende Bienen gesehen. Und wo es Bienen gibt, gibt es Honig. Und wo es Honig gibt, könnte es Met geben.", sourceObjective = "Sammelt 8 Honigfrosthonig für Sonova Schneeweh.", progress = "Ich kann es schon fast schmecken.", completion = "Das wird genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73692] = { id = 73692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmversorgung", description = "Ich würde keinem Bienenstock den Honig klauen, ohne sicherzugehen, dass sie genug Nahrung haben, um es durch die Kälte zu schaffen. Vor allem, wenn wir letztendlich noch mehr davon wollen.\n\nFrostglockenpollen ist ein klebriges Zeug und etwas empfindlich. Aber wenn Ihr durch ein paar blühende Pflanzen lauft, wird es an Euch kleben, wie Flöhe auf einem Kobold.\n\nDann müsst Ihr es einfach zu einer Biene schaffen, bevor es von Euch wieder runtergeweht wird. Sie werden den Pollen direkt von Euch ablecken. Kitzelt auch ein bisschen!", sourceObjective = "Bringt den Honigfrostbienen Pollen.", completion = "Das sollte für eine Weile genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73694] = { id = 73694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Stasis gefangen", description = "Als die ersten Dracthyr aus ihrem Jahrtausende andauernden Schlummer erwachten, brachen wir von der Verbotenen Insel zu den Dracheninseln auf. Aber noch nicht alle Dracthyr waren frei. Tief verborgenen in den Horten warteten noch mehr von uns in Stasis.\n\nWir brauchen Eure Hilfe. Reist zum Froststeingewölbe und versucht, mehr von unseren Freunden zu finden. Eine meiner Heilschwingen würde sich freuen, Euch zu begleiten. Sucht Euch diejenige aus, die zu Euren Bedürfnissen passt.\n\nEs ist Zeit, dass sie sich wie wir hinaus in die Welt wagen.", sourceObjective = "Befreit in Stasis gefangene Dracthyr im Froststeingewölbe.", completion = "Es wärmt mir das Herz, so viele Neuankömmlinge zu sehen. Wir werden unser Bestes tun, sie an all die Änderungen in der Welt zu gewöhnen, die sich seit ihrem Schlaf zugetragen haben.\n\nVielen Dank, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[73698] = { id = 73698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolie Polie Molie" }
quests[73703] = { id = 73703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf nach Orgrimmar", description = "{name}, Etrigg möchte, dass Ihr zu ihm in die Feste Grommash kommt.\n\nEr scheint Euch viel zu sagen zu haben.", sourceObjective = "Sprecht mit Etrigg in der Feste Grommash in Orgrimmar.", completion = "Ah, {name}. Danke für Euer Kommen. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73704] = { id = 73704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokale Spezialitäten", description = "Nun, da wir die Grundlage des Gebräus herausgefunden haben, müssen die Gewürze dazu.\n\nMacht Gebrauch von dem rudimentären Winterpelz, das ich Euch beigebracht habe, und erkundigt Euch nach lokalen Zutaten, die zu dem Geschmacksprofil passen. Versucht mal mit Kazzi zu sprechen. Nach dem, was ich mitbekommen habe, ist sie eine Art Händlerin.\n\nDas fertige Gebräu wird eine Mischung aus Zwergen- und Winterpelztraditionen, was angesichts der Situation passend erscheint.\n\nUnd wenn wir Glück haben, schmeckt es halbwegs gut!", sourceObjective = "Fragt Kazzi nach Zutaten, um das Gebräu zu aromatisieren.", progress = "Geht raus und fragt. Sie wird Euch nicht beißen.\n\nEs sei denn, Ihr bittet sie aus Versehen darum, schätze ich.", completion = "Na dann, sehen wir mal, was wir damit machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[73707] = { id = 73707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TICKET: Glimmeroggspiele", description = "<In unordentlicher Handschrift geschrieben und fast unmöglich zu lesen.>\n\nGLÜCKWUNSCH, LOAMMBESUCHER! IHR HABT EIN TICKET FÜR DEN BESTEN WETTBEWERB IN DER ZARALEKHÖHLE GEFUNDEN: DIE GLIMMEROGGSPIELE!\n\nDie Spiele findet Ihr im Süden der Zaralekhöhle. Achtet einfach auf den Pulk glücklicher Drogbar! Verpasst nicht unsere tollen Aktivitäten wie...\n\n<Bis auf den Namen \"Brogg\" ist der Rest der Seite unleserlich.>", sourceObjective = "Besucht Glimmerogg im Süden der Zaralekhöhle.", completion = "Glück gehabt! Ihr habt ein Ticket für die Glimmeroggspiele gefunden!\n\nAber Ihr braucht noch etwas anderes, um reinzukommen, Brul.", sourceObjectiveStatus = "unverified-source-field" }
quests[73708] = { id = 73708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahlen fürs Spielen", description = "Ganz gleich, ob Ihr eingeladen wurdet oder einfach vorbeigekommen seid. Drogbar, Niffen oder {race}. Für die Glimmeroggspiele müssen alle zahlen.\n\nSogar ich, und ich bin der Veranstalter hier!\n\n<Brogg zeigt aggressiv auf sein eigenes Ticket.>\n\nIch weiß, dass Ihr nicht über die richtige Währung verfügt, aber Ihr könntet Snacks für alle besorgen. Und wir lieben Pilze und Fisch! Bringt Brogg etwas zu essen und wir sind quitt. Alles klar?", sourceObjective = "Sammelt 4 Glimmerpilze und 4 Echolauererfleisch in der Nähe von Glimmerogg.", progress = "Habt Ihr die ganze Teilnahmegebühr? Nein, später zahlen geht nicht. Brogg hatte genug Schnorrer.", completion = "Gut gemacht, Oberländer. Jetzt hat Brogg genug zu essen für eine ganze Woche!\n\n...Ich meine, wir haben Snacks für alle!\n\nUnd jetzt raus mit Euch. Und viel Spaß noch, Brul!", sourceObjectiveStatus = "unverified-source-field" }
quests[73709] = { id = 73709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleiner Freundschaftsdienst", description = "Brogg zählt heute mehr Leute als Gebühren. Gefällt mir nicht. Das macht mich rasend!\n\nJa, Glimmerogg ist beliebt, aber kein Ponyhof. Wir haben Regeln, und alle müssen sich daran halten.\n\nIhr seht aus wie jemand, der das Kleingedruckte lesen und Regeln befolgen kann. Wenn Ihr die Eindringlinge, die Brogg behumsen, loswerdet, habe ich vielleicht etwas für Euch.", sourceObjective = "Entdeckt 6 Eindringlinge und werft sie aus den Glimmeroggspielen.", completion = "Brogg dankt Euch für Euer gutes Auge und Eure Disziplin, kleiner Brul.\n\nDenkt daran, haltet Euch an die Regeln... Wenn ein Stein sich selbst hebt, mogelt jemand.", sourceObjectiveStatus = "unverified-source-field" }
quests[73710] = { id = 73710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fels um Fels", description = "Ah, <ein Herausforderer/eine Herausforderin>! Ihr glaubt also, Storul Schwerstein bei diesem berühmten Steinhebemarathon besiegen zu können?\n\nHA! <törichter Oberländer/törichte Oberländerin>. Niemand kann es mit Storul aufnehmen! Niemand hat JEMALS solche Stärke gezeigt wie ich.\n\nAber Ihr könnt es ja versuchen. Die Niederlage wird Euch eine wertvolle Lektion erteilen: Wahre Stärke kommt durch Kampf!\n\nOder Storul wird <einen neuen Freund/eine neue Freundin> haben, <der/die> ihn beim Krafttraining anhimmelt! Also los, Brul!", sourceObjective = "Schließt Storul Schwersteins Gewichthebespaß ab.", progress = "Was? Ihr habt doch nicht etwa Angst, zu verlieren? Lasst Euch nicht von Angst beherrschen, bevor Ihr überhaupt anfangt.\n\nMacht es einfach, Brul. Storul wird Euch einen fairen Wettbewerb bieten.", completion = "Sehr gut, Brul! Kein Schwächling mehr!\n\nAber auch wenn Ihr bewiesen habt, dass Ihr genauso viel heben könnt wie ich, seid Ihr immer noch nicht so großartig wie Storul.\n\nNoch nicht.\n\nAuf große Herausforderer wie Euch warten noch mehr Steine.", sourceObjectiveStatus = "unverified-source-field" }
quests[73711] = { id = 73711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markierter Champion", description = "Ihr habt Euch in Storuls Herausforderung gut geschlagen, aber das macht Euch noch nicht zu einem Champion wie ihn.\n\nUm auf mein Niveau zu kommen, müsst Ihr jetzt den größten Fels heben. Keinen echten, einen im Geist.\n\nIhr müsst Euch dem stellen, was jeder Drogbar fürchtet... und verehrt! Ihr müsst den Segen von Carcaxas erhalten, dem großen Tochterwurm.\n\nAber Carcaxas gewährt ihr Zeichen nur jenen, die ENTSCHLOSSENHEIT beweisen und KEINE ANGST VOR ÜBLEN GERÜCHEN haben.\n\nSeid Ihr bereit, Euch dieser Herausforderung zu stellen? HABT IHR ES DRAUF, BRUL?!", sourceObjective = "Erhaltet Carcaxas' Zeichen.", progress = "Habt Ihr den Segen des großen Tochterwurms erhalten? Nein? \n\nDann stellt Ihr es Euch nicht fest genug vor. Stellt Euch vor, wie Ihr Carcaxas besiegt. Und jetzt los!", completion = "{race}! Ich kann das Zeichen von Carcaxas an Euch riechen.\n\nDer große Tochterwurm hat Euch zu einem Champion wie mich gemacht! Strorul spürt, dass Ihr stärker seid. Ihr RIECHT stärker!\n\nJetzt könnt Ihr jeden Stein in Eurem Weg bewegen. Aber bleibt weiter konzentriert. Großartigkeit erfordert ständige körperliche und geistige Stärke. Eines Tages werdet Ihr so großartig sein wie Storul. Das ist der Weg von Glimmerogg!\n\nUnd nicht vergessen: Wir suchen jetzt nach Partnern. Man sieht sich am Wochenende beim Krafttraining.", sourceObjectiveStatus = "unverified-source-field" }
quests[73715] = { id = 73715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein munteres Treiben", description = "Eine der Herausforderungen bei der Gründung eines neuen Dorfs liegt immer darin, Baumaterialien zu finden. Zum Glück bringt uns das Meer oft genau das, was wir brauchen.\n\nNehmt mein Boot, segelt um die Insel und sammelt Treibholz in Netzen. Doch seid vorsichtig, dies könnte ungewollte Aufmerksamkeit erregen!", sourceObjective = "Sammelt Treibholz in Tukkaraqs Boot.", completion = "Gute Arbeit! Damit können wir neue Unterkünfte bauen sowie Werkzeug und was wir sonst noch benötigen, um hier zu leben.\n\nAlles davon wird einem guten Zweck dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[73716] = { id = 73716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Älteste der Aylaag", sourceObjective = "Euer Geist steckt voller Leben, junger {class}. Ich freue mich über den Respekt, den Ihr mir zollt, und gebe Euch dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
