quests[74117] = { id = 74117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltene Beute", description = "Seltene und gefährliche Kreaturen lauern um die Horte der Verbotenen Insel. Wenn Ihr und Eure Verbündeten Euch in diesem Land sicher fühlen wollt, solltet Ihr diese Bedrohungen jagen.", sourceObjective = "Jagt die besonderen Bedrohungen auf der Verbotenen Insel.", progress = "Gibt es weiterhin Gefahren, die durch das Land streifen?", completion = "Ich bin froh, dass Ihr Euch um diese Bedrohungen gekümmert habt. Sie haben sicher bekommen, was sie verdient haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[74118] = { id = 74118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenforschen", description = "Hattet Ihr schon die Gelegenheit, den Himmelfuchsbau zu besuchen? Ein sehr aufregender Ort, wie ich höre. Höhlenforscher der Expedition haben mit ihrer Vermessung begonnen und an der Decke sogar einige Greifhaken angebracht, aber sie wurden von wilden Slyvern vertrieben.\n\nKönnt Ihr mir einen Gefallen tun? Geht in den Himmelfuchsbau, holt die zurückgelassene Ausrüstung und untersucht die Decke auf verborgene Felsspalten. Wer weiß, was darin verborgen sein könnte?", sourceObjective = "Untersucht die Decke des Himmelfuchsbaus mithilfe der Kletterausrüstung der Drachenschuppenexpedition, die Ihr in der Höhle findet.", progress = "Habt Ihr dort etwas Interessantes gefunden?", completion = "Gut gemacht! Meine Forschung und mein Schreiben finden nie ein Ende. Ich bin froh, dass Ihr selbst gesehen habt, was in diesem Bau haust.", sourceObjectiveStatus = "unverified-source-field" }
quests[74119] = { id = 74119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Anglers", description = "Sagt, habt Ihr bemerkt, wie gut man hier angeln kann? Die Drachenschädelinsel hat sicher einige gute Orte, um die Leine auszuwerfen.\n\nWarum geht Ihr nicht hin und fangt etwas fürs Abendessen? Aber passt auf. Wir müssen ein paar Fänge für später beiseitelegen.", sourceObjective = "Fangt am Angelloch der Drachenschädelinsel Fische oder bestückt es damit.", completion = "Dank Euch wird es heute Abend ein Festmahl geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[74120] = { id = 74120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühlingserwachen", description = "Falls Ihr nach Arbeit sucht - ich habe gehört, dass es in den Siedlungen in der Nähe großer Städte - Goldhain, Kharanos, Dolanaar und Azurwacht - Magier geben soll, die Eiersucher anstellen, die ihnen bei ihren Forschungen helfen. Ich kenne keine Einzelheiten, aber die werden sie Euch sicher gerne geben.", sourceObjective = "Sprecht mit einem Frühlingssammler in Goldhain, Kharanos, Dolanaar oder Azurwacht.", completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[74282] = { id = 74282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authentische Autorisierung", description = "Die Wichtigkeit dieser Expedition darf nicht unterschätzt werden. Ich versichere Euch, alle Teilnehmer werden in die Geschichte eingehen... zusammen mit mir, versteht sich!\n\nWenn ich eine bemerkenswerte Entdeckung machen kann, wäre mein Vermächtnis als Gelehrter gesichert! Aber was werden wir finden? Eine Kopie von Neltharions Unterschrift? Einen seiner persönlichen Briefe? Ich kann kaum erwarten, etwas zu finden, das ich mit meinen Bewunderern teilen kann. Außerdem brauche ich mehr Bewunderer!\n\nWenn Ihr so freundlich wärt, etwas Denkwürdiges für mich zu finden, werde ich Euch reich entlohnen! Ich kann bezahlen!", sourceObjective = "Findet einen versiegelten Brief an Neltharion.", progress = "Habt Ihr irgendetwas finden können?", completion = "Was für ein großartiger Fund! Mir wird ganz schwindelig.\n\nOh, ich kann es kaum erwarten, über diese Entdeckung zu schreiben und unsere Erkenntnisse zu veröffentlichen. Wir werden veröffentlichen... oder beim Versuch vergehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[74291] = { id = 74291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blau ist meine Lieblingsfarbe", sourceObjective = "Sprecht mit Kirygosa und kehrt dann zu den Azurarchiven zurück.", completion = "Zurück an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[74292] = { id = 74292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefgrottengeheimnisse" }
quests[74293] = { id = 74293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie vergessen", description = "Viridia ist zuversichtlich, dass in diesen Kammern noch weitere Dracthyr schlummern könnten, längst vergessen inmitten von Neltharions Relikten.", sourceObjective = "Befreit in Stasis gefangene Dracthyr in den Gewölben von Zskera.", completion = "Es wärmt mir das Herz, so viele Neuankömmlinge zu sehen. Wir werden unser Bestes tun, sie an die Änderungen zu gewöhnen, die sich seit ihrem Schlaf zugetragen haben.\n\nVielen Dank, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[74294] = { id = 74294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nötigen Schlüssel", description = "Kann ich Euch vertrauen? Das sind die einzigen Schlüssel, die wir haben. Wenn wir die verlieren, können wir keine verschlossene Tür mehr öffnen.\n\nHier, nehmt sie und schließt damit die Türen in dieser Kammer auf. Ihr seht aus, wie <ein Held/eine Heldin>. Seid mutig! Stoßt die Türen weit auf! Dann findet Ihr Ruhm, oder... ähm... irgendwas anderes Tolles! Sterbt nur nicht.\n\nVielleicht finden wir noch mehr Schlüssel, doch dazu werden wir die Insel absuchen müssen.", sourceObjective = "Nehmt die Schlüssel von Tacha bei den Gewölben von Zskera.", completion = "Verliert bloß diese Schlüssel nicht. Habe ich das schon gesagt? Ich glaube schon.", sourceObjectiveStatus = "unverified-source-field" }
quests[74296] = { id = 74296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 3/3" }
quests[74297] = { id = 74297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 3/1" }
