quests[74333] = { id = 74333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armethyst" }
quests[74334] = { id = 74334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukünftige Aspekte", description = "Meine Brüder haben kein Interesse daran, die Splitterflammen zu untersuchen oder Glutthal zu helfen.\n\nEs beunruhigt mich, dass wir uns in unseren Bemühungen verzetteln, aber ich verstehe auf Anhieb ihre Motivationen bezüglich unserer nächsten Schritte gegen Fyrakk.\n\nIch werde Glutthal helfen, so wie ich es versprochen habe, aber vielleicht sollten wir die hiesigen Niffen um Hilfe bitten...", sourceObjective = "Schlagt Honigpelz als Führerin vor.", completion = "Vielen Dank, dass Ihr uns weiter helft, {name}. Glutthal klärt Euch darüber auf, was wir bisher in Erfahrungen bringen konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[74335] = { id = 74335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Moment der Besinnung", description = "Ich verstehe nicht, was Turi Flackerflamme und ihre Magier dazu getrieben hat, zu versuchen, was sie heute hier getan haben. Aber ich verstehe den Schmerz, seine Familie zu verlieren. Ich verstehe die Angst und das Bedauern, das einen auf Schritt und Tritt verfolgt.\n\nIch muss über vieles nachdenken. Ich kann mir vorstellen, dass Kalecgos auf den Dracheninseln noch viel zu erledigen hat, also kehrt mit ihm zurück. Ich werde Euch bald folgen... Ich brauche etwas Zeit, um über die heutigen Ereignisse nachzudenken.", sourceObjective = "Kehrt zu Kalecgos im Azurblauen Gebirge zurück.", completion = "Surigosa und Azuregos sind kaum die einzigen Mitglieder meines Schwarms, die meinen gemäßigteren Umgang mit dem Missbrauch von Magie in Frage stellen. Ich bin für ihre Sichtweise dankbar... und auch für ihre Bereitschaft, meinen Optimismus in Schach zu halten.\n\nDennoch hoffe ich, dass sie die Dinge eines Tages so sehen wie ich.\n\nKommt. Wir haben noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
