quests[74352] = { id = 74352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirbelnder Zephyr" }
quests[74354] = { id = 74354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte allerorten", description = "Es ist... seltsam, Sindragosa zu sehen, auf alle Arten echt bis aufs Körperliche.\n\nHört zu, ich bin dankbar, dass Ihr beide meinetwegen den weiten Weg auf Euch genommen habt. Die Inseln klingen wirklich wunderbar, aber ich habe viele Jahre damit verbracht, Winterquell zu säubern. Ich lasse die Arbeit nicht unfertig liegen. Magie ist überall und leider nicht immer gut.\n\nWenn Ihr helfen möchtet, der Versteckte Hain ist auf meiner Liste als Nächstes dran. Dort liegen Überreste von Totems, die noch eine Art von Magie verströmen. Würdet Ihr ein paar Stücke von ihnen sammeln?", sourceObjective = "Sammelt 5 totemische Ruinen im Versteckten Hain.", progress = "Und dieser ist, denke ich, recht harmlos...", completion = "Ich danke Euch. Sehen wir uns das mal genauer an.", sourceObjectiveStatus = "unverified-source-field" }
quests[74355] = { id = 74355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urzeitliche Verzierung", description = "Wie bemerkenswert! Ihr könnt eine so große Auswahl von besonderen Edelsteinen daran anbringen, um seine Macht zu verstärken!\n\nIhr solltet zurück in die Gewölbe von Zskera reisen und ein urzeitliches Juweliersset suchen. Ja, das werdet Ihr brauchen.\n\nDerartige Edelsteine herzustellen, erfordert besondere Werkzeuge. Sobald wir diese haben, können wir die Macht des Rings gänzlich erforschen! Bei diesen grenzenlosen Möglichkeiten schwirrt mir der Kopf...", sourceObjective = "Findet ein urzeitliches Juweliersset und einen urzeitlichen Amboss in den Gewölben von Zskera.", progress = "Wart Ihr fündig?", completion = "Das ist viel mehr, als ich erwartet habe!\n\nIch hätte mir nie träumen lassen, solche Wunder zu sehen. Mit diesen Werkzeugen könnten wir sogar einen weiteren Ring herstellen! Nur für den Fall, dass Ihr diesen verliert... oder wenn Ihr einen weitergeben... \n\nOh, verzeiht! Das war anmaßend. Es ist nur so... wunderbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[74356] = { id = 74356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück bei den Blauen", description = "Ich hatte wohl eine gute Idee.\n\nHoffen wir nun, dass das Thema der Inseln nun wieder auf dem Tisch ist. Ich bin froh, dass Haleh so entspannt ist. Sie verdient es.", sourceObjective = "Kehrt zu den Azurarchiven zurück.", completion = "Wir müssen für Haleh auch hier eine Thermalquelle finden. \n\n<Sindragosa lächelt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[74359] = { id = 74359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung der Plünderer", description = "Wir haben nicht als Einzige bemerkt, dass die Stürme über der Verbotenen Insel nachlassen.\n\nEs sind noch andere hergekommen, die alles plündern, was sie finden können, und ihre Beute in Kisten verstecken. Wenn sie Neltharions alte Schatzkisten verwenden, werden sie sich noch wundern, wenn die Verzauberung der Truhen sie dann aussperrt. Wir werden die Plünderer in der Gegend beseitigen müssen, um die Verzauberungen zu durchbrechen.\n\nSeht, ob Ihr einen gestohlenen Gegenstand zurückholen könnt, insbesondere mein altes Tagebuch. Ich kann es nirgendwo finden.", sourceObjective = "Holt Atrenoshs Tagebuch aus einer Truhe auf der Verbotenen Insel zurück.", progress = "Konntet Ihr es finden?", completion = "Habt Dank, {name}.\n\nMeine Welt hat sich enorm verändert, seit ich zum letzten Mal etwas dort hineingeschrieben habe. Es wird sicher interessant, es zu lesen, nach allem, was ich jetzt weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[74374] = { id = 74374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wichtiges Erbstück", description = "Ich kann Euch dabei anleiten, Eure Opfergabe für die Ahnen herzustellen, aber Ihr werdet zwei Dinge brauchen.\n\nZuerst müsst Ihr die Grundlagen beherrschen! Arugi kann Euch das Kochen lehren, wenn Ihr es noch nicht könnt.\n\nAls Zweites brauche ich mein altes Kochbuch. Wir werden etwas ganz Besonderes zubereiten, das Draenor und Azeroth verbindet, da brauche ich das zum Nachschlagen. \n\nGeht mein Buch aus dem Gasthaus besorgen, dann können wir anfangen.", sourceObjective = "Lernt die Grundlagen des Kochens und beschafft Koch Torkas Kochbuch.", progress = "Habt Ihr mein Buch gefunden? Es liegt irgendwo im Gasthaus.", completion = "Ah, da haben wir es ja. Es mag unscheinbar wirken, aber das gute Stück hat es durch das Dunkle Portal geschafft! \n\nDas ist ein Familienerbstück aus der Zeit, bevor es die Horde gab. Ich weiß, das ist ungewöhnlich für einen {race}. Meine Uroma, Köchin Barasha, hat bei jedem Kosh'harg die Rezepte aller Klans gesammelt. Wenn ich es richtig verstanden habe, hat sie niemand anderem zugetraut, es richtig hinzubekommen, also hat sie alles aufgeschrieben! Was wir an Geschichten über ihre großartige Sturheit haben...\n\nGenug in Erinnerungen geschwelgt! Zeit, in der Küche aktiv zu werden! Hoffentlich seid Ihr bereit, denn wir haben einiges an Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[74375] = { id = 74375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsergebnisse zusammentragen", description = "Es spielt keine Rolle mehr, wie die Splitterflammen herkamen: Jetzt müssen wir in Erfahrung bringen, weshalb. Was befindet sich in diesem Gewölbe, auf das Sarkareth es abgesehen hat?\n\n{name}, wenn Ihr in ihrem Lager seid, sucht nach Notizen, Forschungstexten, Tagebüchern... was immer Aufschluss über ihre Absichten geben könnte. Bitte bringt mir, was ihr finden könnt.", sourceObjective = "Findet heraus, warum die Expedition der Splitterflammen in der Zaralekhöhle ist.", progress = "Konntet Ihr schon etwas herausfinden?", completion = "Die Notizen offenbaren... Beunruhigendes, aber sie erklären nicht, warum Sarkareth versucht, Aberrus zu finden und sich Zutritt zu verschaffen.\n\nWir können es wohl nur herausfinden, wenn wir ihn einholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74376] = { id = 74376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdichtete Überreste der Stürme", description = "Die Primalistenforscher in dieser Gegend wären daran interessiert, dies genauer zu untersuchen.", sourceObjective = "Bringt die verdichteten Überreste der Stürme zu Brendormi im Morgen der Primalisten.\n\nBereitgestellter Gegenstand:", completion = "Faszinierend! Ich werde meine Befunde an die anderen Forscher in Valdrakken weitergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[74377] = { id = 74377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Krabbe kentern lassen" }
quests[74378] = { id = 74378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Sturms" }
quests[74379] = { id = 74379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weyr rastet, der rostet", description = "Während wir Dracthyr in Stasis gehalten wurden, waren die Zauberverschworenen unsere Wärter, uralte Diener von Malygos dem Spruchwirker. Obwohl er vor Jahren getötet wurde, sind seine ehemaligen Diener dem verstorbenen Aspekt und ihrer Aufgabe, das Land abzuschirmen, noch treu. Sie sind eine Gefahr für jeden verirrten, verwundeten oder anderweitig beeinträchtigten Dracthyr.\n\nSpäher berichten von einem recht großen Zauberverschworenen, der Jagd auf entkommene Dracthyr macht. Dieser tödliche Verfolger muss erledigt werden.", sourceObjective = "Tötet den Schwingenfanger der Zauberverschworenen an der Stätte des alten Weyrn auf der Verbotenen Insel.", completion = "Danke, {class}. Ihr habt die Bedrohung für unsere Rettungs- und Bergungsmissionen auf der Verbotenen Insel beseitigt.\n\nFür manche kommt es zu spät, aber andere Schwingen können dank Eurer Taten wohlbehalten nach Hause fliegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74381] = { id = 74381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Vermächtnisse", description = "Raszageth und ihre Stürme sind verschwunden, aber unsere Probleme sind noch längst nicht beseitigt.\n\nDer Weg zur Insel ist wieder offen und einige unserer Verbündeten sind zurückgekehrt, um ein Basislager zu gründen. Sarkareth und die Splitterflammen sind jedoch auch auf dem Weg dorthin.\n\nWir müssen die Insel sichern. Wir würden Eure Hilfe sehr schätzen.", sourceObjective = "Sprecht am Sitz der Aspekte mit der Gesandten der Heilschwingen, um mehr über die Ereignisse auf der Verbotenen Insel zu erfahren.", progress = "Ah, ein Abenteurer! Hat Glutthal Euch geschickt?", completion = "Zum Glück wurden unsere Späher nicht von unseren Feinden entdeckt. Die Inkarnationen und die Splitterflammen sind beide fähige Gegner. Ich bin nicht sicher, ob wir sie noch einmal überwachen können, ohne Vergeltung fürchten zu müssen.\n\nDie Lage spitzt sich zu. Einige Dracthyr sind bereits auf die Insel zurückgekehrt, aber sie werden einige Hilfe brauchen, um eine Operationsbasis zu errichten.\n\nIhr werdet bald viel zu tun haben, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[74382] = { id = 74382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinschaftliches Festmahl" }
quests[74389] = { id = 74389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kaldera filmen", description = "Die Gliederfüßer in der Kaldera der Heiler sind wirklich bösartig. Einer unserer Gyrokopter wird dort vermisst!\n\nUnsere Expedition hat ein unbemanntes Fluggerät zur Erkundung dort hingeschickt, aber es ist noch nicht zurückgekehrt. Könnt Ihr nach dem Gyrokopter suchen? Ihr könntet die Fauna der Kaldera mit seiner Kamera aufnehmen.", sourceObjective = "Fliegt über die Kaldera der Heiler und nehmt die Tiere dort mit Eurer Kamera auf.", completion = "Gut gemacht! Mit all diesen Fotos ist unsere Dokumentation vollständig!", sourceObjectiveStatus = "unverified-source-field" }
quests[74390] = { id = 74390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Beute", description = "Dieses Land birgt zahllose Gelegenheiten für fähige Jäger. Wir möchten, dass Ihr Euch der Jagd anschließt.\n\nEinige dieser Bedrohungen sind recht wild. Ich wage kaum, es zu sagen, aber die größten Bedrohungen sind intelligent und bösartig. Wenn wir alle zusammenarbeiten, können wir die Insel zu einer sicheren Zuflucht machen, wie sie es früher war.", sourceObjective = "Jagt Elitekreaturen auf der Verbotenen Insel.", completion = "Ich mag, wie Ihr Euch um Probleme kümmert. Sie haben sicher bekommen, was sie verdient haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[74391] = { id = 74391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Harpuniers", description = "Sagt, habt Ihr bemerkt, wie gut man hier angeln kann? Die Drachenschädelinsel hat sicher einige gute Orte.\n\nWarum geht Ihr nicht hin und fangt etwas fürs Abendessen? Aber passt auf. Wir müssen ein paar Fänge für später beiseitelegen.", sourceObjective = "Sammelt 3 Oschihappen von Oschis am Angelloch der Drachenschädelinsel.", progress = "Ich kann diese frischen Fische schon fast schmecken!", completion = "Ich habe schon von \"gehobener Küche\" gehört. Ich weiß nicht genau, was das ist, aber ich weiß, dass wir heute gut essen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[74393] = { id = 74393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Schlachtfeldruinen", description = "Die Lage ist schlimmer, als wir dachten.\n\nDurch Ihre Vorherrschaft in der Luft sind wir deutlich im Hintertreffen. Sie haben vor, ihren mächtigen Ältesten aus Aberrus zu befreien. Wenn wir das zulassen, könnten wir die Kontrolle über dieses Gebiet endgültig verlieren.\n\nSucht Feldkommandant Ignax in den Schlachtfeldruinen auf und erkundigt Euch, was Ihr tun könnt, um das Blatt in der Schlacht zu wenden. Wir werden in Kürze zu Euch stoßen.", sourceObjective = "Sucht Feldkommandant Ignax in den Schlachtfeldruinen.", completion = "Es tut gut, hier draußen einen Verbündeten zu sehen. Das ist gerade das Beste, was uns passieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[74415] = { id = 74415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Opfergabe", description = "Nun, da wir alles auf der Liste haben, müsst Ihr es nur noch zusammenstellen, oder? Das kann doch so schwer nicht sein.\n\nÄhm... Das überlasse ich aber Euch. Ich sehe zu.", sourceObjective = "Kocht die Gerichte der Orcs und platziert dann das Festmahl für die Ahnen auf den Opfergabenstein.", progress = "Ist Eure Aufgabe abgeschlossen?", completion = "Ihr habt Eure Sache gut gemacht. Es kommt nur selten vor, dass die Ahnen vor einem Opfer in diese Welt kommen und sich manifestieren. Eure Gabe muss wahrlich würdig gewesen sein. Ich hoffe, dass Durak zu schätzen weiß, welche Ehre ihm gerade zuteilwurde.\n\nSobald das Om'gora beendet ist, solltet Ihr die Nachrichten weitergeben, die Ihr für die anderen erhalten habt. Ich denke, das wäre ihm sehr recht.\n\n<Sie zwinkert Euch kurz zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[74433] = { id = 74433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge zurückbringen", description = "<Dieser Dolch, der tief im Brustkorb des Riesenwurms Eisbrecher steckte, als er gefunden wurde, gehörte Saza. Es ist offensichtlich, dass Saza tapfer gekämpft hat und dem Monster vor ihrem Tod schwere Verletzungen zugefügt hat.\n\nDiese Klinge sollte in ihr Dorf zurückgebracht werden, damit ihr Klan einen Abschluss finden kann.>", sourceObjective = "Bringt Sazas Dolch zu den Winterpelzen.", progress = "Das ist... Sazas Dolch. Warum habt Ihr ihren Dolch? Oh...", completion = "<Als Ihr Jyrra die Neuigkeit mitteilt, seufzt sie und ihre Augen sind von Tränen getrübt.>\n\nHabt Dank, dass Ihr den Dolch zurückgebracht und uns von ihrer Tapferkeit berichtet habt. Saza hat verbissen für ihre Familie gekämpft. So |A:furblan-d-26:0:1.00|a|A:furblan-d-30:0:1.00|a|A:furblan-d-15:0:1.00|a ich es |A:furblan-d-25:0:1.00|a|A:furblan-d-14:0:1.00|a|A:furblan-d-4:0:1.00|a|A:furblan-d-24:0:1.00|a |A:furblan-d-34:0:1.00|a|A:furblan-d-36:0:1.00|a|A:furblan-d-12:0:1.00|a würde.\n\nIch hätte mit Euch gehen sollen. |A:furblan-d-27:0:1.00|a|A:furblan-d-8:0:1.00|a|A:furblan-d-26:0:1.00|a|A:furblan-d-4:0:1.00|a |A:furblan-d-17:0:1.00|a|A:furblan-d-19:0:1.00|a|A:furblan-d-27:0:1.00|a|A:furblan-d-20:0:1.00|a|A:furblan-d-11:0:1.00|a|A:furblan-d-8:0:1.00|a\n\nEntschuldigt, {name}. Ich stehe in Eurer Schuld. \n\n\n\nOh, ich werde dich vermissen, kleine Schwester...", sourceObjectiveStatus = "unverified-source-field" }
quests[74436] = { id = 74436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmwarnung", description = "Ah, {class}! Ich wusste, ich würde Euch am rechten Ort zur rechten Zeit finden.\n\nDie Elemente bedrohen die Dracheninseln nicht nur in unserer aktuellen Zeit, sondern auch darüber hinaus. Geht zum Temporalen Konflux und reist durch den Riss in die Zukunft, die von den Primalisten überrannt wurde.\n\nSprecht dort mit Soridormi. Sie wird Euch alles Weitere erklären.", sourceObjective = "Sprecht mit Soridormi in der Zukunft der Primalisten. Das Portal zur Zukunft der Primalisten findet Ihr am Temporalen Konflux in Thaldraszus.", completion = "So sehen wir uns also wieder, {name}. Wir brauchen erneut Eure Hilfe, fürchte ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[74437] = { id = 74437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf gegen den Sturm", description = "In dieser zukünftigen Zeitlinie gewinnen die Primalisten trotz unserer Anstrengungen an Stärke. Wenn sie dieses Tal überrennen und den Temporalen Konflux bedrohen, werden sie vielleicht zu einem Problem für die übrigen Zeitwege.\n\nWir beschützen die Zeitwege bereits vor mehr als genug Bedrohungen.\n\nDrängt sie zurück, {name}. Wir müssen diese Gefahr unter Kontrolle halten. Sprecht mit Tarnormu, um Vorräte zu erhalten, die Ihr vielleicht braucht.", sourceObjective = "Deckt Euch mit allen nötigen Vorräten ein und schließt in der Zukunft der Primalisten das Ereignis \"Der Zorn des Sturms\" ab.", progress = "Wir können nicht zulassen, dass die Primalisten andere Perioden unserer Geschichte bedrohen.", completion = "Ihr seid eine Inspiration für die Wenigen, die uns noch bleiben, {class}.\n\nDie Bedrohung mag vorerst zurückgedrängt sein, aber wir müssen unsere Wacht fortsetzen, damit die übrigen Zeitwege nicht in noch größerer Gefahr schweben als zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[74440] = { id = 74440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windsucher Avash" }
quests[74441] = { id = 74441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adlermeisterin Niraak" }
quests[74442] = { id = 74442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plunder eines Drachen...", description = "Grüße! Ich suche nach mächtigen Gegenständen aus der Vergangenheit meines Schwarms.\n\nWir haben eine Geschichte voller großer Krieger und Kampfstärke, und ich möchte Gegenstände finden, die uns dem wieder näherbringen.\n\nIch habe gehört, Ihr habt diese Gewölbe gefunden. Wenn Ihr darin etwas Interessantes findet, würdet Ihr es mir zeigen?", sourceObjective = "Sucht ein Objekt für Voraxian in den Gewölben von Zskera.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Oh, das ist... bestimmt etwas?\n\nEs sieht nicht aus, als könnte man es als Waffe benutzen, aber ich schätze, ich kann es mal untersuchen. Man weiß ja nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[74443] = { id = 74443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...ist des anderen Drachen Schatz?", description = "Ich muss zugeben, dass ich hier überfordert bin.\n\nEs wurde schon von den schwarzen Drachen hergestellt, die Verzierung am Knauf passt. Aber ich habe keine Ahnung, was es sein soll. Was vermutlich beabsichtigt ist.\n\nWie ich höre, habt Ihr die Inseln bereist. Habt Ihr vielleicht Ideen, an wen wir uns wenden sollten?", sourceObjective = "Sprecht mit Voraxian auf der Verbotenen Insel.", progress = "Das ist ein faszinierendes Objekt. Es wäre verlockend, Evorian zu sagen, dass es eine Waffe ist. Nur, um zu sehen, was passiert, wenn er sie benutzen will... Aber lieber nicht. Das könnte wirklich gefährlich werden.\n\nObwohl es amüsant wäre, wenn er die Schuppen ein wenig versengt bekommt.", completion = "Ihr glaubt, dieser Veritistrasz kann helfen? Ein Versuch kann nicht schaden.\n\nGute Idee, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[74444] = { id = 74444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/3 C and D" }
quests[74445] = { id = 74445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/1 C and D" }
quests[74447] = { id = 74447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbale Archäologie", description = "Wo sollten wir diesen Veritistrasz treffen?\n\nAm Rubinlebensschrein? Ihr versucht auch ganz sicher nicht gerade, mich Alexstrasza vorzustellen?\n\nNein? Nun gut! Dann sehen wir uns am Rubinlebensschrein!", sourceObjective = "Sprecht mit Veritistrasz.", progress = "Hoffen wir, dass es etwas Spannendes ist!", completion = "Nun, das ist ein wenig enttäuschend.\n\nIch schätze, ein altes Gerät zur Eierpflege gehört auch zur Kultur, auch wenn es nicht sonderlich aufregend ist.\n\nWenn Ihr noch etwas Interessantes in den Gewölben findet, würde ich es mir gerne ansehen.", sourceObjectiveStatus = "unverified-source-field" }
