quests[74468] = { id = 74468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/2 D and E" }
quests[74476] = { id = 74476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsche Zeit, falscher Schleim", description = "Laut den Ermittlern hier gab es bei der Beseitigung der Zeitanomalie aus der Grenze des Äons ein paar Nebenwirkungen. Dabei sind offenbar diese Schleime durch den Zeitstrom geschlüpft.\n\nOh! Oh! Zeitschleime! Das sind Zeitschleime! Ha.\n\nKönntet Ihr jedenfalls ein paar davon beseitigen?", sourceObjective = "Tötet 12 Zeitschleime.", completion = "Ich habe die Geräusche, wie Ihr die Schleime getötet habt, zu Referenzzwecken aufgenommen. Ich hoffe, das ist in Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[74488] = { id = 74488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rusziona rennt", description = "Schwarze Welpen haben die Agilität eines Steins, aber das versuchen sie mit ihrer beeindruckenden Höchstgeschwindigkeit wieder wettzumachen. Aber passt in den Kurven auf!\n\n: Stürmt vorwärts.\n: Verhindert die Bewegung nach vorn.\n: Stellt sämtlichen Elan wieder her. Nur auf dem Boden verwendbar.", sourceObjective = "Helft Rusziona, durch die Ringe zu gleiten.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[74489] = { id = 74489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zhoomsa", description = "Wenn es ums Gewinnen geht, können Bronzewelpen leichtsinnig werden, also passt auf die Zeitwege auf!\n\n: Verwandelt in ein ausgewachsenes Exemplar und erhöht die Geschwindigkeit.\n: Stellt 1 Elan wieder her, bis sämtlicher Elan wiederhergestellt ist.\n: Setzt Abklingzeiten zurück.", sourceObjective = "Helft Zhusadormu, durch die Ringe zu gleiten.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[74490] = { id = 74490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaleth für unterwegs", description = "Blaue Welpen versuchen, wo es nur gut, abzukürzen, aber passt darauf auf, nicht durch die Ringe zu blinzeln!\n\n: Blinzelt vorwärts und macht einen Spurt.\n: Erhöht die Vorwärtsbeschleunigung.\n: Verbraucht 'Arkane Beschleunigung' und stellt Elan wieder her.", sourceObjective = "Helft Zalethgos, durch die Ringe zu gleiten.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[74491] = { id = 74491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Posidriss in bester Position", description = "Grüne Welpen haben eine Affinität für kurze Nickerchen und Geschwindigkeitsschübe, gebt also Euer Bestes, um auf Trab zu bleiben.\n\n: Fliegt nach oben und stellt 1 Elan wieder her.\n: Erhöht die Dauer von 'Winde des Lebens' um 5 Sek.\n: Sprintet immer, wenn Ihr Elan wiederherstellt, vorwärts.", sourceObjective = "Helft Posidriss, durch die Ringe zu gleiten.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
